	[85003.0] = "{85003, \"[周卡]天命周卡\", 85005, 27, 2, 5, 999999, 5, 1, 0, {}, {{effect_type=33,val=85003}}, {}, {}, \"\", 1, 0, 2, {}, 0, 0, 0, {50}, \"周卡\", \"\", 0, 0}",
