	[80147.0] = "{80147, \"意志具象\", 80110, 500, 0, 3, 999999, 10, 0, 0, {}, {}, {}, {}, \"在极限意志活动期间掉落的意志具象，这是索隆强大意志的具象体，可以在活动商城兑换奖励\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"\", 0, 0}",
