	[81004.0] = "{81004, \"巧克力\", 81004, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"制作巧克力蛋糕必备的巧克力，可通过巧克力猎人任务和情人节甜蜜商城获得，捐献后可以增加<div fontcolor=#9e501b>积分*10</div>并获得<div fontcolor=#9e501b>甜蜜积分币*10</div>\\n活动结束后，使用可以获得<div fontcolor=#9e501b>贝里*100000</div>\", 1, 0, 2, {}, 0, 0, 0, {2}, \"活动道具\", \"作用：活动道具\", 0, 0}",
	[51218.0] = "{51218, \"七武海\", 51218, 0, 2, 5, 1, 1, 1, 0, {}, {{effect_type=25,val=91318}}, {}, {}, \"称号<div fontcolor=#9e501b>「七武海」</div>累计充值6000获得\\n<div fontcolor=#9e501b>气血+15%，攻击+15%，防御+15%，速度+16%</div>\", 1, 0, 2, {}, 1, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[16038.0] = "{16038, \"护盾符石\", 16038, 0, 2, 4, 999999, 1, 1, 0, {{10450,2200}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>护盾:</div>战斗开始，以自身血量的4%为全队附加护盾，持续2回合，该效果不可叠加\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「护盾」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[51215.0] = "{51215, \"水手\", 51215, 0, 2, 5, 1, 1, 1, 0, {}, {{effect_type=25,val=91315}}, {}, {}, \"称号<div fontcolor=#9e501b>「水手」</div>累计充值2000获得\\n<div fontcolor=#9e501b>气血+8%，攻击+8%，防御+8%，速度+8%</div>\", 1, 0, 2, {}, 1, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[89060601.0] = "{89060601, \"[极品]抑法套装随机部位\", 8806, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机部位（耳环、项链、戒指、手镯）的[极品]6星破法神装\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n攻击+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>对法师单位伤害+15%\", 1, 0, 2, {}, 0, 5, 0, {}, \"神装\", \"\", 0, 0}",
	[51202.0] = "{51202, \"荣耀军团\", 51202, 0, 2, 4, 1, 1, 1, 1, {}, {{effect_type=25,val=91302}}, {}, {}, \"称号<div fontcolor=#9e501b>「荣耀军团」</div>在“组队竞技场”中获得，持续7天，\\n<div fontcolor=#9e501b>全体气血+800，攻击+150</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[99090403.0] = "{99090403, \"4星魔甲戒指\", 9010003, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【4星魔甲戒指】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n防御+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【魔甲】：自身受到攻击时，对攻击者造成自身生命值上限2.8%的伤害，该伤害无视防御\", 1, 0, 2, {}, 0, 4, 0, {}, \"神装\", \"\", 0, 0}",
	[39055.0] = "{39055, \"守护之礼\", 39051, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"甚平降临冒险大陆时带来的礼物，开启可随机获得： \\n<div fontcolor=#9e501b>钻石*200</div> \\n<div fontcolor=#9e501b>限定召唤卷*2</div> \\n<div fontcolor=#9e501b>高级探宝券*1</div> \\n<div fontcolor=#9e501b>5星随机碎片*50</div> \\n以上道具中的任意一件。\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[51211.0] = "{51211, \"君临天下\", 51210, 0, 2, 4, 9999999, 1, 1, 0, {}, {{effect_type=25,val=91311}}, {}, {}, \"累充1W定制称号<div fontcolor=#9e501b></div>:永久称号\\n<div fontcolor=#9e501b>生命+3%，攻击+3%，速度+2%，暴击几率+3%</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[80352.0] = "{80352, \"烟花\", 80352, 500, 0, 4, 999999, 10, 0, 0, {}, {}, {}, {}, \"活动特产的烟花道具，使用后可观赏烟花在新年地图上绽放\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"\", 0, 0}",
	[51210.0] = "{51210, \"盛世中国\", 51209, 0, 2, 4, 9999999, 1, 1, 0, {}, {{effect_type=25,val=91310}}, {}, {}, \"国庆节专属称号<div fontcolor=#9e501b></div>:永久称号\\n<div fontcolor=#9e501b>生命+3%，攻击+3%，速度+2%，暴击几率+3%</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[99090803.0] = "{99090803, \"8星魔甲戒指\", 9010003, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【8星魔甲戒指】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n防御+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【魔甲】：自身受到攻击时，对攻击者造成自身生命值上限3.2%的伤害，该伤害无视防御\", 1, 0, 2, {}, 0, 8, 0, {}, \"神装\", \"\", 0, 0}",
	[99040103.0] = "{99040103, \"1星灵咏戒指\", 4010003, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【1星灵咏戒指】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+5%\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+5%\", 1, 0, 2, {}, 0, 1, 0, {}, \"神装\", \"\", 0, 0}",
	[99010302.0] = "{99010302, \"3星勇气项链\", 1010002, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【3星勇气项链】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n防御+3%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>防御+5%\", 1, 0, 2, {}, 0, 3, 0, {}, \"神装\", \"\", 0, 0}",
	[23016.0] = "{23016, \"甜心女仆(永久)\", 23016, 28, 2, 5, 999999, 1, 1, 0, {}, {{effect_type=34,val={106,0,{{3,5000}}}}}, {{106,0,3,5000}}, {}, \"幽冥公主专属<div fontcolor=#9e501b>稀有</div>皮肤，<div fontcolor=#9e501b>永久</div>有效，使用后可为幽冥公主穿戴并解锁相应的形象和头像设置\", 1, 0, 2, {}, 1, 0, 0, {2}, \"皮肤道具\", \"作用：皮肤获取\", 0, 0}",
	[99100104.0] = "{99100104, \"1星神战手镯\", 10010004, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【1星神战手镯】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n攻击+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【神战】：进入战斗后，每回合提升3%伤害，最多叠加5层（该效果不可驱散）\", 1, 0, 2, {}, 0, 1, 0, {}, \"神装\", \"\", 0, 0}",
	[99120302.0] = "{99120302, \"3星神愈项链\", 12010002, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【3星神愈项链】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+7%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【神愈】：治疗时，目标获得等同治疗量22%的护盾（该效果不可被驱散），持续2回合\", 1, 0, 2, {}, 0, 3, 0, {}, \"神装\", \"\", 0, 0}",
	[88829.0] = "{88829, \"元宵节材料礼包\", 90010, 100, 2, 6, 999999, 1, 4, 0, {}, {}, {}, {}, \"开启后可随机获得以下物品：\\n9星英魂*5\\n10星英魂*5\\n传奇自选卡*2\\n传奇随机碎片*100\\n觉醒战技x1 \\n高级好运宝珠x5 \\n极品5星神装自选箱x5 \\n贝里x1亿 \\n经验x1亿\", 1, 0, 2, {}, 0, 0, 0, {2}, \"活动道具\", \"作用：获取道具\", 1, 0}",
	[51204.0] = "{51204, \"春雨绵绵\", 51204, 0, 2, 5, 1, 1, 1, 0, {}, {{effect_type=25,val=91304}}, {}, {}, \"清明节订制称号<div fontcolor=#9e501b>「春雨绵绵」</div>清明节活动期间在“每周限购”中获得，持续永久，\\n<div fontcolor=#9e501b>生命+3%，攻击+3%</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[80150.0] = "{80150, \"莹蓝冰晶\", 80109, 500, 0, 3, 999999, 10, 0, 0, {}, {}, {}, {}, \"深海祝福活动期间掉落的冰晶，阳光照耀下越变越蓝，可以在活动商城兑换奖励\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"\", 0, 0}",
	[99120702.0] = "{99120702, \"7星神愈项链\", 12010002, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【7星神愈项链】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+7%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【神愈】：治疗时，目标获得等同治疗量26%的护盾（该效果不可被驱散），持续2回合\", 1, 0, 2, {}, 0, 7, 0, {}, \"神装\", \"\", 0, 0}",
	[80212.0] = "{80212, \"冒险阅历\", 80212, 500, 0, 3, 999999, 10, 0, 0, {}, {}, {}, {}, \"冒险路上勇士们的阅历经验，冒险日记等级将随着阅历经验的获得而提升\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"\", 0, 0}",
	[51203.0] = "{51203, \"强强联合\", 51203, 0, 2, 3, 1, 1, 1, 1, {}, {{effect_type=25,val=91303}}, {}, {}, \"称号<div fontcolor=#9e501b>「强强联合」</div>在“组队竞技场”中获得，持续7天，\\n<div fontcolor=#9e501b>全体气血+500，攻击+100</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[37007.0] = "{37007, \"夺宝积分\", 37007, 500, 2, 3, 999999, 1, 0, 0, {}, {}, {}, {}, \"在一元夺宝活动中获得的积分，可以在活动商城兑换奖励\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"\", 0, 0}",
	[51101.0] = "{51101, \"天启战神\", 51101, 0, 2, 5, 1, 1, 1, 1, {}, {{effect_type=25,val=91201}}, {}, {}, \"称号<div fontcolor=#9e501b>「天启战神」</div>在“跨服竞技场”中获得，持续7天，\\n<div fontcolor=#9e501b>全体气血+1200，攻击+250</div>\", 1, 0, 2, {}, 1, 0, 0, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[10421.0] = "{10421, \"战技·神之耀\", 10421, 10, 4, 4, 1, 1, 1, 0, {}, {}, {}, {{31,1},{2,0},{7,0}}, \"传说中象征主神荣耀的战技，可升星，根据不同星级附带不同数量的<div fontcolor=#9e501b>技能和属性加成</div>，可供英雄穿戴\", 1, 0, 2, {}, 1, 0, 0, {}, \"英雄战技\", \"作用：技能获得\", 1, 0}",
	[51002.0] = "{51002, \"灵耀王者\", 51002, 0, 2, 4, 1, 1, 1, 1, {}, {{effect_type=25,val=91102}}, {}, {}, \"称号<div fontcolor=#9e501b>「灵耀王者」</div>在“超凡段位赛”中达到排行榜第2-3名（到达王者段位）获得，持续一个赛季时间，\\n<div fontcolor=#9e501b>全体英雄生命+2%，攻击+2%</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[23074.0] = "{23074, \"纯净正义(永久)\", 23074, 28, 2, 5, 999999, 1, 1, 0, {}, {{effect_type=34,val={801,0,{{29,200}}}}}, {{801,0,29,200}}, {}, \"鹤专属<div fontcolor=#9e501b>稀有</div>皮肤，<div fontcolor=#9e501b>永久</div>有效，使用后可为鹤穿戴，并解锁相应的形象和头像设置\", 1, 0, 2, {}, 1, 0, 0, {2}, \"皮肤道具\", \"作用：皮肤获取\", 0, 0}",
	[50919.0] = "{50919, \"最强土豪\", 50919, 0, 2, 4, 999999, 1, 1, 0, {}, {{effect_type=25,val=99021}}, {}, {}, \"称号<div fontcolor=#9e501b>「最强土豪」</div>:在节日活动中获得，是最强土豪的象征，持续30天\\n<div fontcolor=#9e501b>生命+2%，攻击+2%</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[50918.0] = "{50918, \"2020\", 50918, 0, 2, 4, 999999, 1, 1, 0, {}, {{effect_type=25,val=99020}}, {}, {}, \"称号<div fontcolor=#9e501b>「2020」</div>:在“岁初礼赞”活动中获得，是新年的礼物，持续30天\\n<div fontcolor=#9e501b>生命+2%，攻击+2%</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[99010702.0] = "{99010702, \"7星勇气项链\", 1010002, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【7星勇气项链】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n防御+3%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>防御+9%\", 1, 0, 2, {}, 0, 7, 0, {}, \"神装\", \"\", 0, 0}",
	[99040503.0] = "{99040503, \"5星灵咏戒指\", 4010003, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【5星灵咏戒指】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+5%\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗9%\", 1, 0, 2, {}, 0, 5, 0, {}, \"神装\", \"\", 0, 0}",
	[59924.0] = "{59924, \"4级随机宝石\", 59924, 100, 2, 4, 99999999, 1, 4, 0, {}, {}, {}, {}, \"开启可获得随机属性的4级宝石\", 1, 0, 2, {}, 1, 0, 0, {2}, \"宝石礼包\", \"作用:宝石获取\", 1, 0}",
	[50917.0] = "{50917, \"重逢之旅\", 50917, 0, 2, 4, 999999, 1, 1, 0, {}, {{effect_type=25,val=99019}}, {}, {}, \"称号<div fontcolor=#9e501b>「重逢之旅」</div>:在“重逢之旅”活动中获得，持续30天\\n<div fontcolor=#9e501b>生命+2%，攻击+2%</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[50916.0] = "{50916, \"王者之辉\", 50916, 0, 2, 4, 999999, 1, 1, 0, {}, {{effect_type=25,val=99018}}, {}, {}, \"称号<div fontcolor=#9e501b>「王者之辉」</div>:在段位赛“王者之证”活动中获得，持续30天\\n<div fontcolor=#9e501b>生命+2%，攻击+2%</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[38093.0] = "{38093, \"珍稀橙装套\", 38093, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"冒险大陆上极为珍贵的橙色装备，开启后获得：\\n<div fontcolor=#9e501b>海军战刃x1</div>\\n<div fontcolor=#9e501b>角斗士头盔x1</div>\\n<div fontcolor=#9e501b>海军正装x1</div>\\n<div fontcolor=#9e501b>海军战靴x1</div>\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[10452.0] = "{10452, \"中级战技\", 10452, 10, 4, 1, 1, 1, 1, 0, {}, {}, {}, {{3,0},{113,1}}, \"中级战技，附带<div fontcolor=#9e501b>属性加成及1个随机初级技能</div>，可供英雄穿戴后获得；可在锻造屋中<div fontcolor=#9e501b>合成</div>为更高级的高级战技\", 1, 0, 2, {}, 0, 0, 0, {}, \"英雄战技\", \"作用：技能获得\", 1, 0}",
