	[50909.0] = "{50909, \"潮汐猎人\", 50909, 0, 2, 4, 999999, 1, 1, 0, {}, {{effect_type=25,val=99011}}, {}, {}, \"称号<div fontcolor=#9e501b>「潮汐猎人」</div>:在“缤纷盛夏”活动中获得，是成功完成盛夏考验的象征，持续30天\\n<div fontcolor=#9e501b>生命+2%，攻击+2%</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[99100201.0] = "{99100201, \"2星神战耳环\", 10010001, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【2星神战耳环】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n攻击+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【神战】：进入战斗后，每回合提升3.1%伤害，最多叠加5层（该效果不可驱散）\", 1, 0, 2, {}, 0, 2, 0, {}, \"神装\", \"\", 0, 0}",
