	[55902.0] = "{55902, \"勇攀高峰\", 55902, 0, 2, 4, 999999, 5, 1, 0, {}, {{effect_type=35,val=9202}}, {}, {}, \"蕴藏着神秘力量，获得后可激活徽章<div fontcolor=#9e501b>「勇攀高峰」</div>\", 1, 0, 2, {}, 1, 0, 1, {13}, \"徽章道具\", \"作用：徽章激活\", 0, 0}",
	[50907.0] = "{50907, \"冒险勇士\", 50907, 0, 2, 4, 999999, 1, 1, 0, {}, {{effect_type=25,val=99009}}, {}, {}, \"称号<div fontcolor=#9e501b>「冒险勇士」</div>:在“冒险战纪”活动中获得，是冒险大陆上成功完成冒险终极试炼的象征，持续30天\\n<div fontcolor=#9e501b>生命+2%，攻击+2%</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[50906.0] = "{50906, \"冒险骑士团\", 50906, 0, 2, 4, 999999, 1, 1, 0, {}, {{effect_type=25,val=99008}}, {}, {}, \"称号<div fontcolor=#9e501b>「冒险骑士团」</div>:大人的付出被广大船长们所认可。小助手颁发的纪念勋章，希望能一同继续冒险\\n<div fontcolor=#9e501b>生命+10，攻击+10</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[10041.0] = "{10041, \"圣露\", 10038, 9, 2, 4, 999999, 1, 1, 0, {}, {}, {}, {{2,1}}, \"能唤醒万物、滋养生灵的神圣露珠，可用于<div fontcolor=#9e501b>幽灵果实的唤醒</div>\", 0, 0, 2, {}, 0, 0, 0, {1,41}, \"养成道具\", \"作用：幽灵果实养成\", 0, 0}",
