	[39054.0] = "{39054, \"高级召唤礼包\", 80242, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"冒险大陆神秘力量带来的祝福！开启可随机获得： \\n<div fontcolor=#9e501b>高级召唤卷*1</div> \\n<div fontcolor=#9e501b>高级召唤卷*2</div> \\n<div fontcolor=#9e501b>高级召唤卷*5</div> \\n道具中的任意一件。\\n<div fontcolor=#ef3a3a>极低概率可获得强者招募令*1！</div>\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[50305.0] = "{50305, \"海贼王\", 50305, 0, 2, 4, 999999, 1, 1, 0, {}, {{effect_type=25,val=92001}}, {}, {}, \"新服称号礼活动获得，用于激活称号<div fontcolor=#9e501b>「海贼王」\\n挂机经验+10%，上阵气血+300，攻击+60，防御+45</div>\", 1, 0, 2, {}, 1, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[39085.0] = "{39085, \"每日首充精英礼包\", 39083, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"每日首充送好礼！开启可随机获得： \\n<div fontcolor=#9e501b>5星随机碎片*1</div> \\n<div fontcolor=#9e501b>强化训练*150</div> \\n<div fontcolor=#9e501b>生命金卡*1</div> \\n以上道具中的随机一件。\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[99080304.0] = "{99080304, \"3星镇灵手镯\", 8010004, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【3星镇灵手镯】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n暴击率+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>对辅助单位伤害+11%\", 1, 0, 2, {}, 0, 3, 0, {}, \"神装\", \"\", 0, 0}",
	[39116.0] = "{39116, \"极品3星狂怒自选神装\", 39025, 101, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"威力无穷的3星狂怒神装，开启可自选获得以下其中1件神装：\\n<div fontcolor=#9e501b>3星狂怒耳环*1\\n3星狂怒项链*1\\n3星狂怒戒指*1\\n3星狂怒手镯*1</div>\", 1, 0, 2, {1}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[99130802.0] = "{99130802, \"8星极速项链\", 13010002, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【8星极速项链】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n速度+3%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>速度+10%\", 1, 0, 2, {}, 0, 8, 0, {}, \"神装\", \"\", 0, 0}",
	[50022.0] = "{50022, \"和之国武士\", 50022, 0, 2, 4, 999999, 1, 1, 0, {}, {{effect_type=12,val=3800}}, {}, {}, \"和之国火祭活动中可以获取到的头像框，可用于激活<div fontcolor=#9e501b>动态</div>头像框<div fontcolor=#9e501b>「和之国武士」</div>\", 1, 0, 2, {}, 1, 0, 1, {12}, \"头像框道具\", \"作用：头像框激活\", 0, 0}",
	[50048.0] = "{50048, \"大茗鼎鼎头像框\", 50048, 0, 2, 4, 1, 1, 1, 0, {}, {{effect_type=12,val=9100}}, {}, {}, \"珍贵的订制头像框，全服仅此一份，可用于激活<div fontcolor=#9e501b>动态</div>头像框<div fontcolor=#9e501b>「大茗鼎鼎」</div>\\n时效：永久\", 1, 0, 2, {}, 1, 0, 1, {12}, \"头像框道具\", \"作用：头像框激活\", 0, 0}",
	[50047.0] = "{50047, \"蛋糕物语头像框\", 50047, 0, 2, 4, 1, 1, 1, 1, {}, {{effect_type=12,val=9000}}, {}, {}, \"新春活动中获得的头像框，可用于激活<div fontcolor=#9e501b>动态</div>头像框<div fontcolor=#9e501b>「蛋糕物语」</div>\\n时效：永久\", 1, 0, 2, {}, 1, 0, 1, {12}, \"头像框道具\", \"作用：头像框激活\", 0, 0}",
