	[80148.0] = "{80148, \"御田日记\", 80111, 500, 0, 3, 999999, 10, 0, 0, {}, {}, {}, {}, \"在光明乐章活动期间掉落的御田日记，御田日记带来光明和希望，可以在活动商城兑换奖励\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"\", 0, 0}",
