	[99090101.0] = "{99090101, \"1星魔甲耳环\", 9010001, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【1星魔甲耳环】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n防御+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【魔甲】：自身受到攻击时，对攻击者造成自身生命值上限2.5%的伤害，该伤害无视防御\", 1, 0, 2, {}, 0, 1, 0, {}, \"神装\", \"\", 0, 0}",
	[39110.0] = "{39110, \"极品2星神战自选神装\", 39110, 101, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"威力无穷的2星神战神装，开启可自选获得以下其中1件神装：\\n<div fontcolor=#9e501b>2星神战耳环*1\\n2星神战项链*1\\n2星神战戒指*1\\n2星神战手镯*1</div>\", 1, 0, 2, {1}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[55701.0] = "{55701, \"神明眷顾\", 55701, 0, 2, 4, 999999, 5, 1, 0, {}, {{effect_type=35,val=9001}}, {}, {}, \"蕴藏着神秘力量，获得后可激活徽章<div fontcolor=#9e501b>「神明眷顾」</div>\", 1, 0, 2, {}, 1, 0, 1, {13}, \"徽章道具\", \"作用：徽章激活\", 0, 0}",
	[39108.0] = "{39108, \"极品2星镇灵自选神装\", 39108, 101, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"威力无穷的2星镇灵神装，开启可自选获得以下其中1件神装：\\n<div fontcolor=#9e501b>2星镇灵耳环*1\\n2星镇灵项链*1\\n2星镇灵戒指*1\\n2星镇灵手镯*1</div>\", 1, 0, 2, {1}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[99040104.0] = "{99040104, \"1星灵咏手镯\", 4010004, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【1星灵咏手镯】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+5%\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+5%\", 1, 0, 2, {}, 0, 1, 0, {}, \"神装\", \"\", 0, 0}",
