	[39100.0] = "{39100, \"橙色4星装备自选箱\", 39100, 101, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"战力飞升必备的4星橙装，开启可自选获得以下其中1件装备：\\n<div fontcolor=#9e501b>妖刀白刃*1\\n船长战袍*1\\n冰原熊守护*1\\n武装战靴*1</div>\", 1, 0, 2, {1}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[55313.0] = "{55313, \"所向披靡\", 55313, 0, 2, 5, 999999, 5, 1, 0, {}, {{effect_type=35,val=4003}}, {}, {}, \"蕴藏着神秘力量，获得后可激活徽章<div fontcolor=#9e501b>「所向披靡」</div>\", 1, 0, 2, {}, 1, 0, 1, {13}, \"徽章道具\", \"作用：徽章激活\", 0, 0}",
