	[16037.0] = "{16037, \"神体符石\", 16037, 0, 2, 4, 999999, 1, 1, 0, {{10450,2200}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>神体:</div>受携带狂暴/物连/法连单位攻击时，受到的伤害降低10%\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「神体」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[72107.0] = "{72107, \"大炎戒·炎帝\", 72107, 0, 2, 4, 1, 5, 1, 0, {}, {{effect_type=28,val=6}}, {}, {{10180,1}}, \"散发着圣神气息的长枪，可用于激活神技<div fontcolor=#9e501b>大炎戒·炎帝</div>\", 1, 0, 2, {}, 0, 0, 0, {1}, \"神技\", \"作用：神技激活\", 0, 0}",
	[39020.0] = "{39020, \"圣光之心\", 39023, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"战国降临冒险大陆时带来的礼物，开启可获得： \\n<div fontcolor=#9e501b>钻石*200</div> \\n<div fontcolor=#9e501b>限定召唤卷*2</div> \\n<div fontcolor=#9e501b>高级探宝券*1</div> \\n<div fontcolor=#9e501b>5星随机碎片*50</div> \\n以上道具中的任意一件\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[80220.0] = "{80220, \"冒险阅历\", 80212, 500, 0, 3, 999999, 10, 0, 0, {}, {}, {}, {}, \"冒险路上勇士们的阅历经验，冒险日记等级将随着阅历经验的获得而提升\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"\", 0, 0}",
	[89110901.0] = "{89110901, \"[极品]神斩套装随机部位\", 8811, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机部位（耳环、项链、戒指、手镯）的[极品]9星龙威神装\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n暴击率+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【龙威】：攻击造成暴击时，有29%概率额外再造成目标生命上限8%的无视防御伤害（该伤害不超过攻击的1.2倍）\", 1, 0, 2, {}, 0, 5, 0, {}, \"神装\", \"\", 0, 0}",
