	[51217.0] = "{51217, \"船长\", 51217, 0, 2, 5, 1, 1, 1, 0, {}, {{effect_type=25,val=91317}}, {}, {}, \"称号<div fontcolor=#9e501b>「船长」</div>累计充值4000获得\\n<div fontcolor=#9e501b>气血+13%，攻击+13%，防御+13%，速度+13%</div>\", 1, 0, 2, {}, 1, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
