	[80221.0] = "{80221, \"活跃值\", 80215, 500, 0, 3, 999999, 10, 0, 0, {}, {}, {}, {}, \"踏青赏花活动中积攒的暖春活跃值，可用于领取活跃奖励\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"\", 0, 0}",
