	[55901.0] = "{55901, \"友谊与荣耀\", 55901, 0, 2, 4, 999999, 5, 1, 0, {}, {{effect_type=35,val=9201}}, {}, {}, \"蕴藏着神秘力量，获得后可激活徽章<div fontcolor=#9e501b>「友谊与荣耀」</div>\", 1, 0, 2, {}, 1, 0, 1, {13}, \"徽章道具\", \"作用：徽章激活\", 0, 0}",
