	[39013.0] = "{39013, \"春日钻石福袋\", 39015, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"春日钻石福袋，开启可获得： \\n<div fontcolor=#9e501b>钻石*188</div> \\n<div fontcolor=#9e501b>钻石*288</div> \\n<div fontcolor=#9e501b>钻石*388</div> \\n<div fontcolor=#9e501b>钻石*688</div> \\n以上道具中的任意一件。\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[16.0] = "{16, \"公会经验\", 16, 7, 0, 3, 99999999, 4, 0, 0, {}, {}, {}, {{51,1},{52,1}}, \"公会成员贡献的获得，用于提升公会等级，解锁更多公会福利\", 0, 0, 2, {}, 0, 0, 0, {}, \"资产\", \"\", 0, 0}",
	[72103.0] = "{72103, \"冰河时代\", 72103, 0, 2, 4, 1, 5, 1, 0, {}, {{effect_type=28,val=3}}, {}, {{10180,1}}, \"散发着圣神气息的锤，可用于激活神技<div fontcolor=#9e501b>冰河时代</div>\", 1, 0, 2, {}, 0, 0, 0, {1}, \"神技\", \"作用：神技激活\", 0, 0}",
	[39018.0] = "{39018, \"冬日福利\", 39014, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"冬日限量小礼品，开启可获得： \\n<div fontcolor=#9e501b>远航刷新劵*1</div> \\n<div fontcolor=#9e501b>探宝券*1</div> \\n<div fontcolor=#9e501b>5星随机碎片*1</div> \\n<div fontcolor=#9e501b>高级召唤卷*1</div> \\n以上道具中的任意一件。\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[50021.0] = "{50021, \"万圣南瓜夜\", 50021, 0, 2, 4, 999999, 1, 1, 0, {}, {{effect_type=12,val=3700}}, {}, {}, \"万圣狂欢夜的南瓜礼物，有着某种神秘魔力，可用于激活头像框<div fontcolor=#9e501b>「万圣南瓜夜」</div>\", 1, 0, 2, {}, 1, 0, 1, {12}, \"头像框道具\", \"作用：头像框激活\", 0, 0}",
	[50921.0] = "{50921, \"2024\", 50921, 0, 2, 4, 999999, 1, 1, 0, {}, {{effect_type=25,val=99023}}, {}, {}, \"称号<div fontcolor=#9e501b>「2024」</div>:在“元旦贺礼”礼包中获得，是新年的礼物\\n<div fontcolor=#9e501b>生命+2%，攻击+2%</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
