	[99141004.0] = "{99141004, \"10星玄护手镯\", 14010004, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【10星玄护手镯】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n抗控+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【玄护】：自己被附加控制效果时，回复自身生命值上限25%的生命值，1回合只可触发1次\", 1, 0, 2, {}, 0, 10, 0, {}, \"神装\", \"\", 0, 0}",
	[39009.0] = "{39009, \"尊享自选材料包\", 39012, 101, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"极稀有的尊享材料自选礼包，开启可自选：\\n<div fontcolor=#9e501b>强化训练*4000</div>\\n<div fontcolor=#9e501b>神技精石*265</div>\\n<div fontcolor=#9e501b>突破卡*4000</div>\\n<div fontcolor=#9e501b>转换精华*400</div>\\n以上道具中的一件。\", 1, 0, 2, {1}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[39008.0] = "{39008, \"豪华自选材料包\", 39011, 101, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"豪华的材料自选礼包，开启可自选： \\n<div fontcolor=#9e501b>强化训练*2000</div>\\n<div fontcolor=#9e501b>神技精石*130</div>\\n<div fontcolor=#9e501b>突破卡*2000</div>\\n<div fontcolor=#9e501b>转换精华*200</div>\\n以上道具中的一件。\", 1, 0, 2, {1}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 1, 0}",
	[99040202.0] = "{99040202, \"2星灵咏项链\", 4010002, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【2星灵咏项链】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+5%\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+6%\", 1, 0, 2, {}, 0, 2, 0, {}, \"神装\", \"\", 0, 0}",
