	[39000.0] = "{39000, \"幸运宝盒\", 34001, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"被幸运眷顾的宝盒，开启可获得： \\n<div fontcolor=#9e501b>高级召唤卷*1</div> \\n<div fontcolor=#9e501b>高级召唤卷*2</div> \\n<div fontcolor=#9e501b>高级召唤卷*10</div> \\n以上道具中的任意一件。\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
