	[38042.0] = "{38042, \"高级探宝礼包\", 39066, 100, 2, 4, 1, 1, 4, 0, {}, {}, {}, {}, \"可开出以下物品其中之一：五星小丑巴基碎片<div fontcolor=#9e501b>*50</div>、五星雨之希留碎片<div fontcolor=#9e501b>*50</div>、五星小丑巴基碎片<div fontcolor=#9e501b>*25</div>、五星雨之希留碎片<div fontcolor=#9e501b>*25</div>\", 1, 0, 2, {}, 0, 0, 0, {2}, \"活动道具\", \"作用：物品获取\", 0, 0}",
