	[37008.0] = "{37008, \"圣诞币\", 37008, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"用于参与圣诞送礼活动的道具，可用于购买圣诞袜开出的道具。活动结束后使用可获得10钻石\", 1, 0, 2, {}, 0, 0, 0, {2}, \"活动道具\", \"作用：参与圣诞送礼\", 0, 0}",
