	[19011.0] = "{19011, \"蛇蛇果实碎片\", 19011, 38, 7, 4, 999999, 1, 1, 0, {}, {}, {}, {{142,1}}, \"可用于解锁图鉴<div fontcolor=#00ff00 outline=1,#000000>蛇蛇果实</div>，解锁后<div fontcolor=#00ff00 outline=1,#000000>可依据战舰加固等级提升全体伙伴的生命值</div>\", 1, 0, 2, {1}, 1, 0, 0, {1,52}, \"恶魔果实碎片\", \"解锁恶魔果实图鉴\", 0, 0}",
