	[60305.0] = "{60305, \"英魂礼包\", 60305, 100, 2, 5, 999999, 1, 4, 0, {}, {}, {}, {}, \"散发着英魂强烈的气息，开启可随机获得：\\n<div fontcolor=#9e501b>英魂之心*1\\n英魂之心*2\\n英魂之心*3\\n五星随机碎片*5</div>\\n以上道具中的随机一件\\n 英魂之心可用于在英魂商城中兑换海贼新星、草帽联盟和强者三系英雄\", 1, 0, 2, {}, 1, 0, 0, {2}, \"随机礼包\", \"作用：物品获取\", 0, 0}",
