	[52112.0] = "{52112, \"猫蝮蛇\", 52112, 0, 2, 5, 99999999, 1, 1, 0, {}, {{effect_type=25,val=92112}}, {}, {}, \"超级称号<div fontcolor=#9e501b></div>:在星辰宝箱活动中获得，永久称号\\n<div fontcolor=#9e501b>生命+3%，攻击+3%</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[50032.0] = "{50032, \"初春新芽\", 50032, 0, 2, 4, 999999, 1, 1, 0, {}, {{effect_type=12,val=4800}}, {}, {}, \"踏雪拾春活动中可以获取到的头像框，可用于激活头像框<div fontcolor=#9e501b>「初春新芽」</div>\", 1, 0, 2, {}, 1, 0, 1, {12}, \"头像框道具\", \"作用：头像框激活\", 0, 0}",
