	[50015.0] = "{50015, \"贵族气质\", 50015, 0, 2, 4, 999999, 1, 1, 0, {}, {{effect_type=25,val=90013}}, {}, {}, \"贵族的象征，用于激活称号<div fontcolor=#9e501b>「贵族气质」</div>n<div fontcolor=#9e501b>全体气血+200，攻击+40，防御+30</div>\", 1, 0, 2, {}, 1, 0, 1, {}, \"称号道具\", \"作用：称号激活\", 0, 0}",
