	[39030.0] = "{39030, \"魔狼宝藏\", 39031, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"鹰眼降临冒险大陆时带来的礼物，开启可随机获得： \\n<div fontcolor=#9e501b>钻石*200</div> \\n<div fontcolor=#9e501b>限定召唤卷*2</div> \\n<div fontcolor=#9e501b>高级探宝券*1</div> \\n<div fontcolor=#9e501b>5星随机碎片*50</div> \\n以上道具中的任意一件\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[80240.0] = "{80240, \"合服宝箱\", 80242, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"合服大回馈获得的合服宝箱，开启可随机获得以下其中一件： \\n<div fontcolor=#9e501b>钻石*200</div> \\n<div fontcolor=#9e501b>精英召唤卷*2</div> \\n<div fontcolor=#9e501b>高级探宝券*1</div> \\n<div fontcolor=#9e501b>5星随机碎片*50</div>\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[77884321.0] = "{77884321, \"累计充值3000礼包\", 99007, 100, 2, 5, 999999, 1, 4, 0, {}, {}, {}, {}, \"累计充值3000元获得的礼包，使用可获得<div fontcolor=#9e501b>红色装备4*自选2、极品勾玉*4、高级寻宝卷*30、精英忍法帖卷*100、查克拉*1000W、铜币*1000W</div>\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[80302.0] = "{80302, \"斯慕果汁\", 80302, 500, 0, 5, 999999, 10, 0, 0, {}, {}, {}, {}, \"夏洛特·斯慕吉的点心，在万国地图中获得，可前往<div fontcolor=#9e501b>点心兑换</div>活动兑换丰厚奖励\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"\", 0, 0}",
	[59942.0] = "{59942, \"战技导师称号\", 59942, 0, 2, 5, 1, 1, 1, 0, {}, {{effect_type=25,val=93005}}, {}, {}, \"武道宗师冲榜排名第一获得，用于激活称号<div fontcolor=#9e501b>「战技导师」</div>，永久可用\\n<div fontcolor=#9e501b>全体英雄生命+10%，攻击+10%</div>\", 1, 0, 2, {}, 1, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[89100501.0] = "{89100501, \"[极品]神战套装随机部位\", 8810, 100, 2, 5, 999999, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机部位（耳环、项链、戒指、手镯）的[极品]5星神战神装\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n攻击+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【神战】：进入战斗后，每回合提升3.4%伤害，最多叠加5层（该效果不可驱散）\", 1, 0, 2, {}, 0, 5, 0, {}, \"神装\", \"\", 0, 0}",
