	[60132.0] = "{60132, \"不凡传说头像框\", 60132, 0, 2, 4, 999999, 1, 1, 0, {}, {{effect_type=12,val=6100}}, {}, {}, \"在协力段位赛中取得第2-3的好名次时获得\", 1, 0, 2, {}, 0, 0, 0, {}, \"头像道具\", \"作用：获得头像\", 0, 0}",
