	[30006.0] = "{30006, \"神技精石礼包\", 90014, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"珍贵的神技精石礼包，开启后必定获得：\\n<div fontcolor=#9e501b>神技精石x30</div>\", 1, 0, 2, {}, 0, 0, 0, {1,2}, \"礼包\", \"作用：物品获取\", 0, 0}",
