	[89150801.0] = "{89150801, \"[极品]麒麟套装随机部位\", 8815, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机部位（耳环、项链、戒指、手镯）的[极品]8星玄护神装\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n抗控+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【玄护】：自己被附加控制效果时，回复自身生命值上限15%的生命值，1回合只可触发1次\", 1, 0, 2, {}, 0, 5, 0, {}, \"神装\", \"\", 0, 0}",
	[72111.0] = "{72111, \"大·冰河时代\", 72111, 0, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"神技解锁可用于觉醒神技<div fontcolor=#9e501b>大·冰河时代</div>\\n解锁后所有神技<div fontcolor=#9e501b>生命+3%，攻击+3%</div>\", 1, 0, 2, {}, 0, 0, 0, {1}, \"神技\", \"作用：神技激活\", 0, 0}",
	[17008.0] = "{17008, \"混沌意志\", 17008, 100, 2, 3, 999999, 1, 4, 0, {}, {}, {}, {{90,0}}, \"海军皇团力量交织的混沌意志，使用后可从<div fontcolor=#9e501b>海军意志</div>和<div fontcolor=#9e501b>首领意志</div>中随机获得一个\", 1, 0, 2, {}, 0, 0, 0, {1,2}, \"升级材料\", \"作用：物品获取\", 0, 0}",
	[99010403.0] = "{99010403, \"4星勇气戒指\", 1010003, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【4星勇气戒指】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n防御+3%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>防御+6%\", 1, 0, 2, {}, 0, 4, 0, {}, \"神装\", \"\", 0, 0}",
	[17006.0] = "{17006, \"传奇意志\", 17006, 0, 2, 3, 999999, 1, 1, 0, {{1,10000}}, {}, {}, {{116,0}}, \"传奇无光的结晶，可用于<div fontcolor=#9e501b>升级信念</div>传奇之力\", 1, 0, 2, {}, 0, 0, 0, {1,34,37}, \"升级材料\", \"作用：圣物升级\", 0, 0}",
	[37013.0] = "{37013, \"哨子\", 37017, 0, 2, 4, 999999, 1, 1, 0, {}, {}, {}, {}, \"用于参与冬季福袋抽奖活动的道具，每消耗100个哨子可进行一次翻牌。\\n<div fontcolor=#9e501b>活动结束后，使用可1：200转换为贝里，请尽快使用</div>\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"作用：参与活动抽奖\", 0, 0}",
	[99120403.0] = "{99120403, \"4星神愈戒指\", 12010003, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【4星神愈戒指】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+7%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【神愈】：治疗时，目标获得等同治疗量23%的护盾（该效果不可被驱散），持续2回合\", 1, 0, 2, {}, 0, 4, 0, {}, \"神装\", \"\", 0, 0}",
