	[17002.0] = "{17002, \"自由意志\", 17002, 0, 2, 3, 999999, 1, 1, 0, {{1,10000}}, {}, {}, {{116,0}}, \"绯红色的结晶，可用于<div fontcolor=#9e501b>升级信念</div>自由草帽\", 1, 0, 2, {}, 0, 0, 0, {1,34,37}, \"升级材料\", \"作用：圣物升级\", 1, 0}",
	[89110701.0] = "{89110701, \"[极品]神斩套装随机部位\", 8811, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机部位（耳环、项链、戒指、手镯）的[极品]7星龙威神装\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n暴击率+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【龙威】：攻击造成暴击时，有29%概率额外再造成目标生命上限8%的无视防御伤害（该伤害不超过攻击的1.2倍）\", 1, 0, 2, {}, 0, 5, 0, {}, \"神装\", \"\", 0, 0}",
	[16020.0] = "{16020, \"精准符石\", 16020, 0, 2, 4, 999999, 1, 1, 0, {{10450,2000}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>精准:</div>命中提高6%；对携带闪避/迅捷的目标伤害提高5%\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「精准」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[16109.0] = "{16109, \"茶豚符石\", 16108, 0, 2, 5, 999999, 1, 1, 0, {{10460,3}}, {}, {}, {{114,0},{124,0}}, \"茶豚的专属霸气符石，激活后可增加“手枪连射”100%伤害\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：觉醒霸气学习\", 1, 0}",
	[59901.0] = "{59901, \"命运星魄\", 59901, 9, 2, 4, 99999999, 1, 1, 0, {}, {}, {}, {{130,1},{307,1},{59,1}}, \"命盘升级进阶，以及宝石合成的必备高级材料，非常罕见。\", 1, 0, 2, {}, 1, 0, 0, {1}, \"命盘道具\", \"作用：命盘宝石\", 0, 0}",
	[39.0] = "{39, \"星命卡牌\", 39, 7, 0, 3, 99999999, 4, 0, 0, {}, {}, {}, {{105,0}}, \"蕴含着神秘星象力量的卡牌，是占卜的必用材料。可在伟大召唤-星命占卜中抽取五星传说英雄\", 0, 0, 2, {}, 0, 0, 0, {}, \"资产\", \"\", 0, 0}",
	[16107.0] = "{16107, \"灵感符石\", 16107, 0, 2, 5, 999999, 1, 1, 0, {{10460,3}}, {}, {}, {{114,0},{124,0}}, \"<div fontcolor=#9e501b>灵感:</div>使用增益主动技能时，有20%概率使增益持续回合+1，该效果冷却2回合；使用减益技能时，效果触发率+5%\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「灵感」</div>觉醒霸气，英雄将在<div fontcolor=#9e501b>13星</div>开启觉醒\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：觉醒霸气学习\", 1, 0}",
	[90606.0] = "{90606, \"6星英魂自选礼包\", 90500, 101, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"可作为英雄升星的消耗材料，替代非指定的<div fontcolor=#9e501b>5星五皇团英雄</div>\", 1, 0, 2, {1}, 1, 0, 0, {2}, \"礼包\", \"作用：获取道具\", 0, 0}",
	[99090904.0] = "{99090904, \"9星魔甲手镯\", 9010004, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【9星魔甲手镯】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n防御+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【魔甲】：自身受到攻击时，对攻击者造成自身生命值上限3.3%的伤害，该伤害无视防御\", 1, 0, 2, {}, 0, 9, 0, {}, \"神装\", \"\", 0, 0}",
	[23077.0] = "{23077, \"不死鸟(7天)\", 23076, 28, 2, 5, 999999, 1, 1, 0, {}, {{effect_type=34,val={901,604800,{{29,32}}}}}, {{901,604800,29,32}}, {}, \"马尔科专属<div fontcolor=#9e501b>稀有</div>皮肤，<div fontcolor=#9e501b>7天</div>有效，使用后可为马尔科穿戴，并解锁相应的形象和头像设置\", 1, 0, 2, {}, 0, 0, 0, {2}, \"皮肤道具\", \"作用：皮肤获取\", 0, 0}",
	[16104.0] = "{16104, \"制裁符石\", 16104, 0, 2, 5, 999999, 1, 1, 0, {{10460,3}}, {}, {}, {{114,0},{124,0}}, \"<div fontcolor=#9e501b>制裁:</div>攻击时使目标额外受到其生命上限*3%的伤害值（不超过本次所受技能伤害值的30%）\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「制裁」</div>觉醒霸气，英雄将在<div fontcolor=#9e501b>13星</div>开启觉醒\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：觉醒霸气学习\", 1, 0}",
	[80303.0] = "{80303, \"克力饼干\", 80303, 500, 0, 5, 999999, 10, 0, 0, {}, {}, {}, {}, \"夏洛特·克力架的点心，在万国地图中获得，可前往<div fontcolor=#9e501b>点心兑换</div>活动兑换丰厚奖励\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"\", 0, 0}",
	[99040604.0] = "{99040604, \"6星灵咏手镯\", 4010004, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【6星灵咏手镯】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+5%\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+10%\", 1, 0, 2, {}, 0, 6, 0, {}, \"神装\", \"\", 0, 0}",
	[99010803.0] = "{99010803, \"8星勇气戒指\", 1010003, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【8星勇气戒指】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n防御+3%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>防御+10%\", 1, 0, 2, {}, 0, 8, 0, {}, \"神装\", \"\", 0, 0}",
	[16102.0] = "{16102, \"蓄力符石\", 16102, 0, 2, 5, 999999, 1, 1, 0, {{10460,3}}, {}, {}, {{114,0},{124,0}}, \"<div fontcolor=#9e501b>蓄力:</div>本回合无法行动时，下次释放攻击技能时伤害额外提高15%（可叠加，无法被驱散，每次释放攻击技能后移除）\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「蓄力」</div>觉醒霸气，英雄将在<div fontcolor=#9e501b>13星</div>开启觉醒\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：觉醒霸气学习\", 1, 0}",
	[16101.0] = "{16101, \"破裂符石\", 16101, 0, 2, 5, 999999, 1, 1, 0, {{10460,3}}, {}, {}, {{114,0},{124,0}}, \"<div fontcolor=#9e501b>破裂:</div>对带有【护盾】的敌人额外造成5%的伤害，且造成伤害值的30%将直接无视护盾效果\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「破裂」</div>觉醒霸气，英雄将在<div fontcolor=#9e501b>13星</div>开启觉醒\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[16047.0] = "{16047, \"贪婪符石\", 16047, 0, 2, 4, 999999, 1, 1, 0, {{10450,2200}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>贪婪:</div>使用魔法伤害技能时，以伤害量的10%恢复攻击者自身生命值\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「贪婪」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[99120803.0] = "{99120803, \"8星神愈戒指\", 12010003, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【8星神愈戒指】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+7%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【神愈】：治疗时，目标获得等同治疗量27%的护盾（该效果不可被驱散），持续2回合\", 1, 0, 2, {}, 0, 8, 0, {}, \"神装\", \"\", 0, 0}",
	[16046.0] = "{16046, \"驱灵符石\", 16046, 0, 2, 4, 999999, 1, 1, 0, {{10450,2000}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>驱灵:</div>对携带【圣灵】的单位伤害提升10%，若击杀单位则其无法触发【圣灵】的效果\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「驱灵」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[23011.0] = "{23011, \"御龙金甲(7天)\", 23010, 28, 2, 4, 999999, 1, 1, 0, {}, {{effect_type=34,val={104,604800,{{29,16}}}}}, {{104,604800,29,16}}, {}, \"基德专属皮肤，<div fontcolor=#9e501b>7天</div>有效，使用后可为基德穿戴，并解锁相应的形象和头像设置\", 1, 0, 2, {}, 0, 0, 0, {2}, \"皮肤道具\", \"作用：皮肤获取\", 0, 0}",
	[80101.0] = "{80101, \"藏宝图\", 80101, 500, 0, 3, 999999, 10, 0, 0, {}, {}, {}, {}, \"汇集冒险大陆神秘宝藏的地图，仅会在在特殊时期掉落。\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"\", 0, 0}",
	[99070103.0] = "{99070103, \"1星斗战戒指\", 7010003, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【1星斗战戒指】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n攻击+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>对战士单位伤害+7%\", 1, 0, 2, {}, 0, 1, 0, {}, \"神装\", \"\", 0, 0}",
	[89050601.0] = "{89050601, \"[极品]碎盾套装随机部位\", 8805, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机部位（耳环、项链、戒指、手镯）的[极品]6星穿甲神装\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n暴击率+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>对坦克单位伤害+15%\", 1, 0, 2, {}, 0, 5, 0, {}, \"神装\", \"\", 0, 0}",
	[39200.0] = "{39200, \"BIG·MOM天命包\", 39045, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"BIG·MOM天命礼包，开启可随机获得： \\n<div fontcolor=#9e501b>夺宝币*200 \\nBIG·MOM碎片*50(较低概率，同时批量使用5个BIG·MOM天命包则必出BIG·MOM碎片*50)</div>\\n以上道具中的任意一件。\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[16045.0] = "{16045, \"圣灵符石\", 16045, 0, 2, 4, 999999, 1, 1, 0, {{10450,2000}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>圣灵:</div>死亡后化为灵魂，下回合有5%概率以15%生命值复活，每过1回合复活概率递增5%，5回合后必定复活，每场战斗只生效1次\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「圣灵」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[72110.0] = "{72110, \"阿修罗·壹雾银\", 72110, 0, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"索隆的终结技<div fontcolor=#9e501b>阿修罗·壹雾银</div>\\n解锁后所有神技<div fontcolor=#9e501b>生命+3%，攻击+3%</div>\", 1, 0, 2, {}, 0, 0, 0, {1}, \"神技\", \"作用：神技激活\", 0, 0}",
	[10403.0] = "{10403, \"高级召唤卷\", 10405, 9, 2, 4, 999999, 1, 1, 0, {}, {}, {}, {{3,1},{2,1}}, \"记载高等召唤仪式的卷轴，可在高级召唤中召唤<div fontcolor=#9e501b>随机3~5星英雄</div>\", 1, 0, 2, {}, 1, 0, 0, {1,9}, \"召唤道具\", \"作用：英雄召唤\", 1, 0}",
	[16043.0] = "{16043, \"波动符石\", 16043, 0, 2, 4, 999999, 1, 1, 0, {{10450,2200}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>波动:</div>造成魔法伤害时，最终伤害结果会在90-110%之间随机波动\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「波动」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[16042.0] = "{16042, \"专注符石\", 16042, 0, 2, 4, 999999, 1, 1, 0, {{10450,2200}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>专注:</div>战斗开始时，魔法伤害提升10%，持续2回合，该效果不可被驱散\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「专注」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[60207.0] = "{60207, \"阎魔二选一礼包\", 39051, 101, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"开启可自选获得下列1个英雄：\\n<div fontcolor=#9e501b>索隆(新世界)碎片*50\\n御田碎片*50</div>\", 1, 0, 2, {1}, 0, 0, 0, {1}, \"英雄礼包\", \"作用：英雄获取\", 0, 0}",
	[16041.0] = "{16041, \"英勇符石\", 16041, 0, 2, 4, 999999, 1, 1, 0, {{10450,2200}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>英勇:</div>战斗开始时，物理伤害提升10%，持续2回合，该效果不可被驱散\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「英勇」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[16040.0] = "{16040, \"反伤符石\", 16040, 0, 2, 4, 999999, 1, 1, 0, {{10450,2000}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>反伤:</div>受到伤害时，有20%概率反弹30%伤害\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「反伤」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[99041004.0] = "{99041004, \"10星灵咏手镯\", 4010004, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【10星灵咏手镯】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+5%\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+14%\", 1, 0, 2, {}, 0, 1, 0, {}, \"神装\", \"\", 0, 0}",
	[16039.0] = "{16039, \"清心符石\", 16039, 0, 2, 4, 999999, 1, 1, 0, {{10450,2000}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>清心:</div>治疗/复活技能有20%概率清除随机一名队友所有负面状态\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「清心」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[51216.0] = "{51216, \"副船长\", 51216, 0, 2, 5, 1, 1, 1, 0, {}, {{effect_type=25,val=91316}}, {}, {}, \"称号<div fontcolor=#9e501b>「副船长」</div>累计充值3000获得\\n<div fontcolor=#9e501b>气血+10%，攻击+10%，防御+10%，速度+10%</div>\", 1, 0, 2, {}, 1, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[99925.0] = "{99925, \"58R英雄礼包【19星】\", 99911, 101, 2, 5, 999999, 1, 4, 0, {}, {}, {}, {}, \"58R英雄礼包【19星】，打开后可获得\\n<div fontcolor=#9e501b>传奇19星英雄自选卡*1</div>\", 1, 0, 2, {1}, 1, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 1, 0}",
	[39096.0] = "{39096, \"红色4星装备自选箱\", 39096, 101, 2, 5, 999999, 1, 4, 0, {}, {}, {}, {}, \"战力飞升必备的4星红装，开启可自选获得以下其中1件装备：\\n<div fontcolor=#9e501b>风纹天候棒*1\\n将军护甲*1\\n闪光贝雷帽*1\\n风纹战靴*1</div>\", 1, 0, 2, {1}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[99100302.0] = "{99100302, \"3星神战项链\", 10010002, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【3星神战项链】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n攻击+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【神战】：进入战斗后，每回合提升3.2%伤害，最多叠加5层（该效果不可驱散）\", 1, 0, 2, {}, 0, 3, 0, {}, \"神装\", \"\", 0, 0}",
	[85001.0] = "{85001, \"[周卡]钻石周卡\", 85001, 27, 2, 5, 999999, 5, 1, 0, {}, {{effect_type=33,val=85001}}, {}, {}, \"\", 1, 0, 2, {}, 0, 0, 0, {50}, \"周卡\", \"\", 0, 0}",
	[80114.0] = "{80114, \"烈焰之羽\", 80110, 500, 0, 3, 999999, 10, 0, 0, {}, {}, {}, {}, \"在烈焰庇护活动期间掉落的羽毛，虽然人们分不清这是哪位神的羽毛，但是可以在活动商城兑换奖励\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"\", 0, 0}",
	[99100702.0] = "{99100702, \"7星神战项链\", 10010002, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【7星神战项链】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n攻击+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【神战】：进入战斗后，每回合提升3.6%伤害，最多叠加5层（该效果不可驱散）\", 1, 0, 2, {}, 0, 7, 0, {}, \"神装\", \"\", 0, 0}",
	[16036.0] = "{16036, \"吸取符石\", 16036, 0, 2, 4, 999999, 1, 1, 0, {{10450,2200}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>吸取:</div>使用物理伤害技能时，以伤害量的20%恢复攻击者自身生命值\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「吸取」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[55706.0] = "{55706, \"欧皇降临\", 55706, 0, 2, 4, 999999, 5, 1, 0, {}, {{effect_type=35,val=9006}}, {}, {}, \"蕴藏着神秘力量，获得后可激活徽章<div fontcolor=#9e501b>「欧皇降临」</div>\", 1, 0, 2, {}, 1, 0, 1, {13}, \"徽章道具\", \"作用：徽章激活\", 0, 0}",
	[59943.0] = "{59943, \"世界征兵称号\", 59943, 0, 2, 5, 1, 1, 1, 0, {}, {{effect_type=25,val=93006}}, {}, {}, \"无尽试炼冲榜排名第一获得，用于激活称号<div fontcolor=#9e501b>「世界征兵」</div>，永久可用\\n<div fontcolor=#9e501b>全体英雄生命+10%，攻击+10%</div>\", 1, 0, 2, {}, 1, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[80238.0] = "{80238, \"礼花炮\", 80240, 0, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"在花火祭活动中燃放的烟花，燃放时全服玩家可以在主城看到燃放效果，并发放<div fontcolor=#9e501b>全服红包</div>，燃放后可以获得<div fontcolor=#9e501b>随机道具奖励</div>与<div fontcolor=#9e501b>花火积分*12</div>\", 1, 0, 2, {}, 0, 0, 0, {42}, \"活动道具\", \"作用：活动道具\", 0, 0}",
	[99070903.0] = "{99070903, \"9星斗战戒指\", 7010003, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【9星斗战戒指】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n攻击+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>对战士单位伤害+23%\", 1, 0, 2, {}, 0, 9, 0, {}, \"神装\", \"\", 0, 0}",
	[60133.0] = "{60133, \"卓尔不群头像框\", 60133, 0, 2, 3, 999999, 1, 1, 0, {}, {{effect_type=12,val=6200}}, {}, {}, \"在协力段位赛中取得第4-10的好名次时获得\", 1, 0, 2, {}, 0, 0, 0, {}, \"头像道具\", \"作用：获得头像\", 0, 0}",
	[19113.0] = "{19113, \"公斤果实碎片\", 19113, 38, 7, 3, 999999, 1, 1, 0, {}, {}, {}, {{142,1}}, \"可用于解锁图鉴<div fontcolor=#00ff00 outline=1,#000000>公斤果实</div>，解锁后可<div fontcolor=#00ff00 outline=1,#000000>提升全体伙伴攻击力</div>\", 1, 0, 2, {}, 0, 0, 0, {1,52}, \"恶魔果实碎片\", \"解锁恶魔果实图鉴\", 0, 0}",
	[39091.0] = "{39091, \"备战宝盒\", 39041, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"即将迎战和之国专属的备战宝盒！开启可随机获得：  \\n<div fontcolor=#9e501b>钻石*200</div> \\n<div fontcolor=#9e501b>征战约定*20</div> \\n<div fontcolor=#9e501b>高级探宝券*1</div> \\n以上道具中的随机一件。\\n<div fontcolor=#ef3a3a>极低概率可获得5星随机碎片*50！</div>\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[16034.0] = "{16034, \"免伤符石\", 16034, 0, 2, 4, 999999, 1, 1, 0, {{10450,2200}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>免伤:</div>战斗开始时，前2回合免伤提高10%\\n\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「免伤」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[99020603.0] = "{99020603, \"6星狂怒戒指\", 2010003, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【6星狂怒戒指】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n暴击率+3%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>暴击率+8%\", 1, 0, 2, {}, 0, 6, 0, {}, \"神装\", \"\", 0, 0}",
	[16033.0] = "{16033, \"法连符石\", 16033, 0, 2, 4, 999999, 1, 1, 0, {{10450,2400}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>法连:</div>法攻有20%概率触发连击，再次释放技能，伤害、控制率为原来50%\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「法连」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[16032.0] = "{16032, \"命中符石\", 16032, 0, 2, 4, 999999, 1, 1, 0, {{10450,2200}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>命中:</div>效果命中提高3%，暴击降低10%\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「命中」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[55411.0] = "{55411, \"冠军赛·32强\", 55411, 0, 2, 3, 999999, 5, 1, 0, {}, {{effect_type=35,val=6001}}, {}, {}, \"蕴藏着神秘力量，获得后可激活徽章<div fontcolor=#9e501b>「冠军赛·32强」</div>\", 1, 0, 2, {}, 0, 0, 0, {13}, \"徽章道具\", \"作用：徽章激活\", 0, 0}",
	[89040301.0] = "{89040301, \"[极品]灵咏套装随机部位\", 8804, 100, 2, 4, 999999, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机部位（耳环、项链、戒指、手镯）的[极品]3星灵咏神装\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+5%\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+7%\", 1, 0, 2, {}, 0, 3, 0, {}, \"神装\", \"\", 0, 0}",
	[99130503.0] = "{99130503, \"5星极速戒指\", 13010003, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【5星极速戒指】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n速度+3%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>速度+7%\", 1, 0, 2, {}, 0, 5, 0, {}, \"神装\", \"\", 0, 0}",
	[16030.0] = "{16030, \"迟缓符石\", 16030, 0, 2, 4, 999999, 1, 1, 0, {{10450,1600}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>迟缓:</div>速度降低10%，生命值提高3%\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「迟缓」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[39061.0] = "{39061, \"嘉年华蛋糕\", 39061, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"一块好友分享给你的嘉年华蛋糕！开启可随机获得： \\n<div fontcolor=#9e501b>钻石*48</div> \\n<div fontcolor=#9e501b>钻石*68</div> \\n<div fontcolor=#9e501b>钻石*88</div> \\n<div fontcolor=#9e501b>钻石*188</div> \\n以上道具中的任意一件。\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[72109.0] = "{72109, \"鸟笼\", 72109, 0, 2, 4, 1, 1, 1, 1, {}, {}, {}, {}, \"明哥的终结技<div fontcolor=#9e501b>鸟笼</div>\\n解锁后所有神技<div fontcolor=#9e501b>生命+2%，攻击+2%</div>\", 1, 0, 2, {}, 0, 0, 0, {1}, \"神技\", \"作用：神技激活\", 0, 0}",
	[99001.0] = "{99001, \"新春红包\", 10800, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"2019年新春红包，可随机获得<div fontcolor=#9e501b>100-300钻石</div>\", 1, 0, 2, {}, 0, 0, 0, {2}, \"红包\", \"\", 0, 0}",
	[19105.0] = "{19105, \"笔笔果实碎片\", 19105, 38, 7, 3, 999999, 1, 1, 0, {}, {}, {}, {{142,1}}, \"可用于解锁图鉴<div fontcolor=#00ff00 outline=1,#000000>笔笔果实</div>，解锁后可<div fontcolor=#00ff00 outline=1,#000000>提升全体伙伴的生命值</div>\", 1, 0, 2, {}, 0, 0, 0, {1,52}, \"恶魔果实碎片\", \"解锁恶魔果实图鉴\", 0, 0}",
	[16027.0] = "{16027, \"魔免符石\", 16027, 0, 2, 4, 999999, 1, 1, 0, {{10450,2200}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>魔免:</div>受到的魔法伤害降低5%\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「魔免」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[37012.0] = "{37012, \"美酒\", 37015, 0, 2, 4, 999999, 1, 1, 0, {}, {}, {}, {}, \"用于参与酒豪抽奖活动的道具，和索隆对饮来换取奖励，每消耗100桶美酒可进行一次翻牌。\\n<div fontcolor=#9e501b>活动结束后，使用可1：200转换为贝里，请尽快使用</div>\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"作用：参与活动抽奖\", 0, 0}",
	[16026.0] = "{16026, \"抗暴符石\", 16026, 0, 2, 4, 999999, 1, 1, 0, {{10450,2000}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>抗暴:</div>被暴击概率降低5%\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「抗暴」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[89070601.0] = "{89070601, \"[极品]止战套装随机部位\", 8807, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机部位（耳环、项链、戒指、手镯）的[极品]6星斗战神装\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n攻击+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>对战士单位伤害+15%\", 1, 0, 2, {}, 0, 5, 0, {}, \"神装\", \"\", 0, 0}",
	[89100901.0] = "{89100901, \"[极品]神战套装随机部位\", 8810, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机部位（耳环、项链、戒指、手镯）的[极品]9星神战神装\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n攻击+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【神战】：进入战斗后，每回合提升3.4%伤害，最多叠加5层（该效果不可驱散）\", 1, 0, 2, {}, 0, 5, 0, {}, \"神装\", \"\", 0, 0}",
	[16012.0] = "{16012, \"灭魂符石\", 16012, 0, 2, 4, 999999, 1, 1, 0, {{10450,1600}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>灭魂:</div>受击方10%概率4回合无法复活；对有神佑/保命的伤害+5%\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「灭魂」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
