	[16022.0] = "{16022, \"抗控符石\", 16022, 0, 2, 4, 999999, 1, 1, 0, {{10450,2000}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>抗控:</div>效果抵抗提高4%，效果抵抗越高，抵抗控制成功率越高\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「抗控」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[80115.0] = "{80115, \"御田日记\", 80111, 500, 0, 3, 999999, 10, 0, 0, {}, {}, {}, {}, \"在光明乐章活动期间掉落的御田日记，御田日记带来光明和希望，可以在活动商城兑换奖励\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"\", 0, 0}",
