	[55311.0] = "{55311, \"攻无不克\", 55311, 0, 2, 3, 999999, 5, 1, 0, {}, {{effect_type=35,val=4001}}, {}, {}, \"蕴藏着神秘力量，获得后可激活徽章<div fontcolor=#9e501b>「攻无不克」</div>\", 1, 0, 2, {}, 0, 0, 0, {13}, \"徽章道具\", \"作用：徽章激活\", 0, 0}",
