	[39137.0] = "{39137, \"极品4星魔甲自选神装\", 39109, 101, 2, 5, 999999, 1, 4, 0, {}, {}, {}, {}, \"威力无穷的4星魔甲神装，开启可自选获得以下其中1件神装：\\n<div fontcolor=#9e501b>4星魔甲耳环*1\\n4星魔甲项链*1\\n4星魔甲戒指*1\\n4星魔甲手镯*1</div>\", 1, 0, 2, {1}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
