	[52141.0] = "{52141, \"熊(机械)\", 52141, 0, 2, 5, 99999999, 1, 1, 0, {}, {{effect_type=25,val=92141}}, {}, {}, \"超级称号<div fontcolor=#9e501b></div>:在星辰宝箱活动中获得，永久称号\\n<div fontcolor=#9e501b>生命+3%，攻击+3%</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[10426.0] = "{10426, \"战技·神之耀\", 10421, 0, 4, 4, 1, 5, 1, 0, {}, {{effect_type=30,val={10421,5}}}, {}, {{31,1},{2,0},{7,0}}, \"传说中象征主神荣耀的战技，可升星，根据不同星级附带不同数量的<div fontcolor=#9e501b>技能和属性加成</div>，可供英雄穿戴\", 1, 0, 2, {}, 1, 0, 0, {}, \"英雄战技\", \"作用：技能获得\", 1, 0}",
	[16002.0] = "{16002, \"神力符石\", 16002, 0, 2, 4, 999999, 1, 1, 0, {{10450,2200}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>神力:</div>物理伤害提升5%；攻击额外提高60点\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「神力」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[55709.0] = "{55709, \"神力觉醒\", 55709, 0, 2, 5, 999999, 5, 1, 0, {}, {{effect_type=35,val=9009}}, {}, {}, \"蕴藏着神秘力量，获得后可激活徽章<div fontcolor=#9e501b>「神力觉醒」</div>\", 1, 0, 2, {}, 1, 0, 1, {13}, \"徽章道具\", \"作用：徽章激活\", 0, 0}",
	[14001.0] = "{14001, \"强者招募令\", 14001, 0, 2, 4, 999999, 1, 1, 0, {}, {}, {}, {{2,0},{3,0},{43,0},{53,0},{4,0}}, \"伟大召唤的必备品，用于在伟大召唤中召唤<div fontcolor=#9e501b>4、5星英雄</div>\", 1, 0, 2, {}, 0, 0, 0, {1,19}, \"伟大召唤道具\", \"作用：伟大召唤\", 1, 0}",
	[99140501.0] = "{99140501, \"5星玄护耳环\", 14010001, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【5星玄护耳环】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n抗控+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【玄护】：自己被附加控制效果时，回复自身生命值上限15%的生命值，1回合只可触发1次\", 1, 0, 2, {}, 0, 5, 0, {}, \"神装\", \"\", 0, 0}",
	[52106.0] = "{52106, \"佛之战国\", 52106, 0, 2, 5, 99999999, 1, 1, 0, {}, {{effect_type=25,val=92106}}, {}, {}, \"超级称号<div fontcolor=#9e501b></div>:在星辰宝箱活动中获得，永久称号\\n<div fontcolor=#9e501b>生命+3%，攻击+3%</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[14000.0] = "{14000, \"神将之灵\", 14000, 0, 2, 4, 999999, 1, 1, 0, {}, {}, {}, {}, \"破碎的大海意志，集齐100个可定向召唤出神将英雄：\\n<div fontcolor=#9e501b>艾斯</div>或<div fontcolor=#9e501b>香克斯</div>\", 1, 0, 2, {}, 0, 0, 0, {}, \"神将道具\", \"作用：神将召唤\", 1, 0}",
	[59944.0] = "{59944, \"海贼之巅称号\", 59944, 0, 2, 5, 1, 1, 1, 0, {}, {{effect_type=25,val=93007}}, {}, {}, \"超神阵容冲榜排名第一获得，用于激活称号<div fontcolor=#9e501b>「海贼之巅」</div>，永久可用\\n<div fontcolor=#9e501b>全体英雄生命+15%，攻击+15%</div>\", 1, 0, 2, {}, 1, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[11999.0] = "{11999, \"无限十连券\", 10406, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"使用后进行10次高级招募，且<div fontcolor=#9e501b>概率获得3-5星英雄！！！</div>若对招募结果不满意，可<div fontcolor=#9e501b>重新招募</div>，直到招募到心仪的英雄\", 1, 0, 2, {}, 1, 0, 0, {47}, \"召唤道具\", \"作用：英雄召唤\", 1, 0}",
