	[60101.0] = "{60101, \"V5专属头像框\", 60101, 0, 2, 4, 999999, 5, 1, 0, {}, {{effect_type=12,val=2300}}, {}, {}, \"达到Vip5时自动激活该头像框\", 1, 0, 2, {}, 1, 0, 1, {}, \"称号道具\", \"作用：头像框激活\", 0, 0}",
