	[99120804.0] = "{99120804, \"8星神愈手镯\", 12010004, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【8星神愈手镯】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+7%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【神愈】：治疗时，目标获得等同治疗量27%的护盾（该效果不可被驱散），持续2回合\", 1, 0, 2, {}, 0, 8, 0, {}, \"神装\", \"\", 0, 0}",
	[11012.0] = "{11012, \"第三块历史正文\", 11012, 0, 2, 5, 1, 1, 1, 0, {}, {}, {}, {}, \"这是第三块红色历史正文，集齐四块红色历史正文，在历史正文收集活动中，定位通往拉夫德鲁的道路，找到onepeace！\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"作用：活动道具\", 1, 0}",
