	[39105.0] = "{39105, \"极品2星穿甲自选神装\", 39105, 101, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"威力无穷的2星穿甲神装，开启可自选获得以下其中1件神装：\\n<div fontcolor=#9e501b>2星穿甲耳环*1\\n2星穿甲项链*1\\n2星穿甲戒指*1\\n2星穿甲手镯*1</div>\", 1, 0, 2, {1}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[99070104.0] = "{99070104, \"1星斗战手镯\", 7010004, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【1星斗战手镯】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n攻击+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>对战士单位伤害+7%\", 1, 0, 2, {}, 0, 1, 0, {}, \"神装\", \"\", 0, 0}",
	[99006.0] = "{99006, \"解锁进阶奖励\", 99006, 500, 0, 4, 999999, 10, 0, 0, {}, {}, {}, {}, \"购买进阶卡之后，可解锁<div fontcolor=#9e501b>「花火映秋」活动进阶奖励</div>，包含<div fontcolor=#9e501b>自选5星英雄，限定头像框和限时称号</div>等，达到指定等级即可领取对应奖励\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"\", 0, 0}",
	[11010.0] = "{11010, \"第一块历史正文\", 11010, 0, 2, 5, 1, 1, 1, 0, {}, {}, {}, {}, \"这是第一块红色历史正文，集齐四块红色历史正文，在历史正文收集活动中，定位通往拉夫德鲁的道路，找到onepeace！\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"作用：活动道具\", 1, 0}",
	[55181.0] = "{55181, \"长环岛·探险\", 55181, 0, 2, 4, 999999, 5, 1, 0, {}, {{effect_type=35,val=2081}}, {}, {}, \"蕴藏着神秘力量，获得后可激活徽章<div fontcolor=#9e501b>「长环岛·探险」</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"徽章道具\", \"作用：徽章激活\", 0, 0}",
