	[50501.0] = "{50501, \"冰天雪地（弃用）\", 50501, 0, 2, 3, 999999, 1, 1, 0, {}, {{effect_type=25,val=90501}}, {}, {}, \"神将限时兑换活动获得，用于激活称号<div fontcolor=#9e501b>「冰天雪地」\\n全体气血+200，攻击+40，防御+30</div>\", 1, 0, 2, {}, 1, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[10800.0] = "{10800, \"贝里红包令\", 10800, 100, 2, 2, 999999, 1, 2, 0, {}, {}, {}, {}, \"小小的红包令折射出了富裕，可在公会中发放<div fontcolor=#9e501b>小清新红包</div>\", 1, 0, 2, {}, 0, 0, 0, {11}, \"红包道具\", \"作用：红包发放\", 1, 0}",
	[10703.0] = "{10703, \"奥术法杖\", 10703, 0, 2, 4, 99, 1, 2, 0, {{{3,150}}}, {}, {}, {{11,1}}, \"由智者施以奥秘之术的法杖，可在幽灵系统中进行<div fontcolor=#9e501b>培养加速</div>\", 1, 0, 2, {}, 0, 0, 0, {37,1}, \"培养道具\", \"作用：培养加速\", 0, 0}",
