	[39166.0] = "{39166, \"火灵礼盒\", 39051, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"冒险大陆上特有的火灵礼盒！开启可随机获得：  \\n<div fontcolor=#9e501b>钻石*200</div> \\n<div fontcolor=#9e501b>火灵环*20</div> \\n<div fontcolor=#9e501b>高级探宝券*1</div> \\n以上道具中的随机一件。\\n<div fontcolor=#ef3a3a>极低概率可获得5星随机碎片*50！</div>\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[10441.0] = "{10441, \"战技·魔之灵\", 10441, 10, 4, 3, 1, 1, 1, 0, {}, {}, {}, {{31,1},{5,0},{71,0}}, \"传说中象征至强魔主的战技，可升星，根据不同星级附带不同数量的<div fontcolor=#9e501b>技能和属性加成</div>，可供英雄穿戴\", 1, 0, 2, {}, 1, 0, 0, {}, \"英雄战技\", \"作用：技能获得\", 1, 0}",
