	[39084.0] = "{39084, \"每日首充幸运礼包\", 39083, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"每日首充送好礼！开启可随机获得： \\n<div fontcolor=#9e501b>5星随机碎片*1</div> \\n<div fontcolor=#9e501b>强化训练*100</div> \\n<div fontcolor=#9e501b>生命金卡*1</div> \\n以上道具中的随机一件。\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[23023.0] = "{23023, \"竹韵清风(7天)\", 23022, 28, 2, 5, 999999, 1, 1, 0, {}, {{effect_type=34,val={108,604800,{{29,32}}}}}, {{108,604800,29,32}}, {}, \"月光莫利亚专属<div fontcolor=#9e501b>稀有</div>皮肤，<div fontcolor=#9e501b>7天</div>有效，使用后可为月光莫利亚穿戴，并解锁相应的形象和头像设置\", 1, 0, 2, {}, 0, 0, 0, {2}, \"皮肤道具\", \"作用：皮肤获取\", 0, 0}",
	[10702.0] = "{10702, \"星辰锤\", 10702, 0, 2, 3, 999999, 1, 2, 0, {{{3,75}}}, {}, {}, {}, \"以星辰之力凝聚的锤子，可在幽灵系统中进行<div fontcolor=#9e501b>培养加速</div>\", 1, 0, 2, {}, 0, 0, 0, {37,1}, \"培养道具\", \"作用：培养加速\", 0, 0}",
	[10417.0] = "{10417, \"回归红包\", 80258, 0, 2, 4, 999999, 1, 4, 0, {}, {{effect_type=41,val={}}}, {}, {}, \"使用可以发放<div fontcolor=#9e501b>全服红包</div>，每个红包可随机获得10~30个时光漂流瓶，每日最多可领取5次红包；【重逢之旅】活动结束后将按1:1比例回收为10万贝里，请尽快使用！\", 0, 0, 2, {}, 0, 0, 0, {1}, \"活动道具\", \"作用：活动道具\", 0, 0}",
	[99120101.0] = "{99120101, \"1星神愈耳环\", 12010001, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【1星神愈耳环】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+7%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【神愈】：治疗时，目标获得等同治疗量20%的护盾（该效果不可被驱散），持续2回合\", 1, 0, 2, {}, 0, 1, 0, {}, \"神装\", \"\", 0, 0}",
	[10415.0] = "{10415, \"幽灵幸运石\", 10415, 9, 2, 4, 999999, 1, 1, 0, {}, {}, {}, {{311,1}}, \"参与幽灵召唤的幽灵幸运石！可在<div fontcolor=#9e501b>幽灵系统</div>中召唤幽灵\", 1, 0, 2, {}, 1, 0, 0, {46}, \"召唤道具\", \"作用：幽灵召唤\", 1, 0}",
	[10412.0] = "{10412, \"橙色万能碎片\", 10412, 0, 2, 4, 999999, 1, 1, 0, {}, {}, {}, {}, \"蕴含英雄灵力的碎片，可以转换为任意<div fontcolor=#9e501b>SS级英雄碎片</div>，进行英雄<div fontcolor=#9e501b>合成或升星</div>\", 0, 0, 2, {}, 1, 0, 0, {}, \"英雄碎片\", \"作用：英雄碎片转换\", 0, 0}",
	[99090602.0] = "{99090602, \"6星魔甲项链\", 9010002, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【6星魔甲项链】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n防御+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【魔甲】：自身受到攻击时，对攻击者造成自身生命值上限3.0%的伤害，该伤害无视防御\", 1, 0, 2, {}, 0, 6, 0, {}, \"神装\", \"\", 0, 0}",
	[88830.0] = "{88830, \"元宵节装备礼包\", 40223, 100, 2, 6, 999999, 1, 4, 0, {}, {}, {}, {}, \"开启后可随机获得以下物品：\\n5星红装自选*5\\n1星金装自选*1\\n2星金装自选*1\\n3星金装自选*1\\n4星金装自选x1 \\n5星金装自选x1 \\n6星金装自选x1\", 1, 0, 2, {}, 0, 0, 0, {2}, \"活动道具\", \"作用：获取道具\", 1, 0}",
	[10411.0] = "{10411, \"果实召唤卷\", 10411, 100, 2, 4, 999999, 1, 1, 0, {}, {}, {}, {}, \"可在魔盒秘宝中召唤<div fontcolor=#00ff00 outline=1,#000000>随机品质的恶魔果实碎片</div>\", 1, 0, 2, {1}, 1, 0, 0, {1,56}, \"召唤道具\", \"作用：恶魔果实召唤\", 1, 0}",
	[80249.0] = "{80249, \"和之国小米酒\", 80249, 500, 0, 4, 999999, 10, 0, 0, {}, {}, {}, {}, \"和之国限定小米酒！ \\n<div fontcolor=#9e501b>火祭活动下次战斗伤害5倍（BOSS挑战除外）</div>\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"\", 0, 0}",
	[99091002.0] = "{99091002, \"10星魔甲项链\", 9010002, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【10星魔甲项链】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n防御+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【魔甲】：自身受到攻击时，对攻击者造成自身生命值上限3.5%的伤害，该伤害无视防御\", 1, 0, 2, {}, 0, 1, 0, {}, \"神装\", \"\", 0, 0}",
	[10410.0] = "{10410, \"蓝色万能碎片\", 10410, 0, 2, 2, 999999, 1, 1, 0, {}, {}, {}, {}, \"蕴含英雄灵力的碎片，可以转换为任意<div fontcolor=#9e501b>A级英雄碎片</div>，进行英雄<div fontcolor=#9e501b>合成或升星</div>\", 0, 0, 2, {}, 1, 0, 0, {9}, \"英雄碎片\", \"作用：英雄碎片转换\", 0, 0}",
