	[99040302.0] = "{99040302, \"3星灵咏项链\", 4010002, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【3星灵咏项链】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+5%\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+7%\", 1, 0, 2, {}, 0, 3, 0, {}, \"神装\", \"\", 0, 0}",
	[16044.0] = "{16044, \"神赦符石\", 16044, 0, 2, 4, 999999, 1, 1, 0, {{10450,2200}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>神赦:</div>提升自身2%攻击力，且自身所受到的单次攻击伤害超过生命上限的40%时，有20%概率令伤害减少30%\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「神赦」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[10401.0] = "{10401, \"普通召唤卷\", 10401, 9, 2, 3, 999999, 1, 1, 0, {}, {}, {}, {{3,0}}, \"记载神秘仪式的卷轴，可在普通召唤中召唤<div fontcolor=#9e501b>随机1~5星英雄</div>\", 1, 0, 2, {}, 0, 0, 0, {1,9}, \"召唤道具\", \"作用：英雄召唤\", 1, 0}",
	[99010901.0] = "{99010901, \"9星勇气耳环\", 1010001, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【9星勇气耳环】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n防御+3%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>防御+11%\", 1, 0, 2, {}, 0, 9, 0, {}, \"神装\", \"\", 0, 0}",
	[16019.0] = "{16019, \"镇压符石\", 16019, 0, 2, 4, 999999, 1, 1, 0, {{10450,2000}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>镇压:</div>对携带生机/再生的目标伤害提高15%\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「镇压」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[23022.0] = "{23022, \"竹韵清风(永久)\", 23022, 28, 2, 5, 999999, 1, 1, 0, {}, {{effect_type=34,val={108,0,{{3,5000}}}}}, {{108,0,3,5000}}, {}, \"月光莫利亚专属<div fontcolor=#9e501b>稀有</div>皮肤，<div fontcolor=#9e501b>永久</div>有效，使用后可为月光莫利亚穿戴，并解锁相应的形象和头像设置\", 1, 0, 2, {}, 1, 0, 0, {2}, \"皮肤道具\", \"作用：皮肤获取\", 0, 0}",
	[80109.0] = "{80109, \"莹蓝冰晶\", 80109, 500, 0, 3, 999999, 10, 0, 0, {}, {}, {}, {}, \"深海祝福活动期间掉落的冰晶，阳光照耀下越变越蓝，可以在活动商城兑换奖励\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"\", 0, 0}",
	[99120901.0] = "{99120901, \"9星神愈耳环\", 12010001, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【9星神愈耳环】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+7%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【神愈】：治疗时，目标获得等同治疗量28%的护盾（该效果不可被驱散），持续2回合\", 1, 0, 2, {}, 0, 9, 0, {}, \"神装\", \"\", 0, 0}",
	[10201.0] = "{10201, \"战神宝箱\", 80007, 100, 2, 4, 999999, 5, 1, 0, {}, {}, {}, {}, \"领取后自动开启，必定获得<div fontcolor=#9e501b>500竞技积分</div>，并有大概率额外掉落<div fontcolor=#9e501b>技能符石x3</div>\", 1, 0, 2, {}, 0, 0, 1, {}, \"竞技宝箱\", \"作用：积分获取\", 1, 0}",
	[50401.0] = "{50401, \"破军之巅（弃用）\", 50401, 0, 2, 4, 1, 5, 1, 1, {}, {{effect_type=25,val=90401}}, {}, {}, \"无尽试炼排行榜排名第一获得，用于激活称号<div fontcolor=#9e501b>「破军之巅」</div>，持续1天\\n<div fontcolor=#9e501b>全体气血+300，攻击+200，防御+30</div>\", 1, 0, 2, {}, 1, 0, 0, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[10200.0] = "{10200, \"竞技宝箱\", 80008, 100, 2, 3, 999999, 5, 1, 0, {}, {}, {}, {}, \"领取后自动开启，必定获得<div fontcolor=#9e501b>300竞技积分</div>，并有较大概率额外掉落<div fontcolor=#9e501b>技能符石x2</div>\", 1, 0, 2, {}, 0, 0, 1, {}, \"竞技宝箱\", \"作用：积分获取\", 1, 0}",
	[89090601.0] = "{89090601, \"[极品]神甲套装随机部位\", 8809, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机部位（耳环、项链、戒指、手镯）的[极品]6星魔甲神装\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n防御+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【魔甲】：自身受到攻击时，对攻击者造成自身生命值上限2.9%的伤害，该伤害无视防御\", 1, 0, 2, {}, 0, 5, 0, {}, \"神装\", \"\", 0, 0}",
	[10103.0] = "{10103, \"竞技挑战券\", 10103, 9, 2, 3, 999999, 1, 2, 0, {}, {}, {}, {{3,1},{2,1}}, \"竞技场挑战对手必备的门票\", 1, 0, 2, {}, 0, 0, 0, {1,16}, \"消耗道具\", \"作用：竞技场挑战\", 0, 0}",
	[99070201.0] = "{99070201, \"2星斗战耳环\", 7010001, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【2星斗战耳环】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n攻击+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>对战士单位伤害+9%\", 1, 0, 2, {}, 0, 2, 0, {}, \"神装\", \"\", 0, 0}",
	[51219.0] = "{51219, \"四皇\", 51219, 0, 2, 5, 1, 1, 1, 0, {}, {{effect_type=25,val=91319}}, {}, {}, \"称号<div fontcolor=#9e501b>「四皇」</div>累计充值8000获得\\n<div fontcolor=#9e501b>气血+16%，攻击+15%，防御+15%，速度+16%</div>\", 1, 0, 2, {}, 1, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[39522.0] = "{39522, \"极品3星神装自选礼包\", 34010, 101, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"开启后可选择获得以下1件随机部位的极品神装：\\n<div fontcolor=#9e501b>3星勇气套装随机一部位\\n3星狂怒套装随机一部位\\n3星斗志套装随机一部位\\n3星灵咏套装随机一部位\\n3星穿甲套装随机一部位\\n3星破法套装随机一部位\\n3星斗战套装随机一部位\\n3星镇灵套装随机一部位\\n3星魔甲套装随机一部位\\n3星神战套装随机一部位\\n3星龙威套装随机一部位\\n3星神愈套装随机一部位\\n3星极速套装随机一部位\\n3星玄护套装随机一部位</div>\", 1, 0, 2, {1}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[89110301.0] = "{89110301, \"[极品]龙威套装随机部位\", 8811, 100, 2, 4, 999999, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机部位（耳环、项链、戒指、手镯）的[极品]3星龙威神装\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n暴击率+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【龙威】：攻击造成暴击时，有27%概率额外再造成目标生命上限8%的无视防御伤害（该伤害不超过攻击的1.2倍）\", 1, 0, 2, {}, 0, 3, 0, {}, \"神装\", \"\", 0, 0}",
	[52136.0] = "{52136, \"夏洛特玲玲\", 52136, 0, 2, 5, 99999999, 1, 1, 0, {}, {{effect_type=25,val=92136}}, {}, {}, \"超级称号<div fontcolor=#9e501b></div>:在星辰宝箱活动中获得，永久称号\\n<div fontcolor=#9e501b>生命+3%，攻击+3%</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[39103.0] = "{39103, \"极品2星斗志自选神装\", 39026, 101, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"威力无穷的2星斗志神装，开启可自选获得以下其中1件神装：\\n<div fontcolor=#9e501b>2星斗志耳环*1\\n2星斗志项链*1\\n2星斗志戒指*1\\n2星斗志手镯*1</div>\", 1, 0, 2, {1}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[10096.0] = "{10096, \"共鸣遗物\", 10096, 9, 2, 4, 999999, 1, 2, 0, {}, {}, {}, {{8,0}}, \"古老而神秘的遗物，可用于赋能创造\", 1, 0, 2, {}, 1, 0, 0, {1}, \"消耗道具\", \"作用：赋能创造\", 0, 0}",
