	[99080503.0] = "{99080503, \"5星镇灵戒指\", 8010003, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【5星镇灵戒指】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n暴击率+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>对辅助单位伤害+15%\", 1, 0, 2, {}, 0, 5, 0, {}, \"神装\", \"\", 0, 0}",
	[34.0] = "{34, \"冠军币\", 34, 7, 0, 3, 99999999, 4, 0, 0, {}, {}, {}, {{121,0}}, \"周冠军赛发放的专属货币，可用于在周冠军赛专属商城中兑换珍稀道具\", 0, 0, 2, {}, 0, 0, 0, {}, \"资产\", \"\", 0, 0}",
	[33.0] = "{33, \"高级竞猜币\", 33, 7, 0, 3, 99999999, 4, 0, 0, {}, {}, {}, {{121,0}}, \"用于周冠军赛中参与竞猜玩法，竞猜结束后将自动转化为冠军币\", 0, 0, 2, {}, 0, 0, 0, {}, \"资产\", \"\", 0, 0}",
	[16011.0] = "{16011, \"降疗符石\", 16011, 0, 2, 4, 999999, 1, 1, 0, {{10450,1600}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>降疗:</div>有20%概率使目标治疗、被治疗效果降低10%，持续3回合\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「降疗」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[32.0] = "{32, \"神技彤石\", 32, 7, 0, 4, 99999999, 4, 0, 0, {}, {}, {}, {{7,1},{10,1}}, \"来自神界的稀有晶石，因其有如太阳般灼热而得名，可用于<div fontcolor=#9e501b>提升神技精炼等级</div>\", 0, 0, 2, {}, 0, 0, 0, {}, \"资产\", \"作用：神技精炼\", 0, 0}",
	[89060801.0] = "{89060801, \"[极品]抑法套装随机部位\", 8806, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机部位（耳环、项链、戒指、手镯）的[极品]8星破法神装\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n攻击+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>对法师单位伤害+15%\", 1, 0, 2, {}, 0, 5, 0, {}, \"神装\", \"\", 0, 0}",
	[31.0] = "{31, \"家园币\", 31, 7, 0, 3, 99999999, 4, 0, 0, {}, {}, {}, {{131,0}}, \"刻有温馨家园图案的硬币，可用于购买家具和萌兽出行所需物资。\", 0, 0, 2, {}, 0, 0, 0, {}, \"资产\", \"\", 0, 0}",
	[30.0] = "{30, \"勇者印记\", 30, 7, 0, 3, 99999999, 4, 0, 0, {}, {}, {}, {{120,0},{123,0}}, \"真正勇者才能持有的印记，用于在跨服竞技场和组队竞技场的积分商城中兑换稀有5星英雄和皮肤碎片等道具\", 0, 0, 2, {}, 0, 0, 0, {}, \"资产\", \"\", 0, 0}",
	[52118.0] = "{52118, \"未来流行·鹰眼\", 52118, 0, 2, 5, 99999999, 1, 1, 0, {}, {{effect_type=25,val=92118}}, {}, {}, \"超级称号<div fontcolor=#9e501b></div>:在星辰宝箱活动中获得，永久称号\\n<div fontcolor=#9e501b>生命+3%，攻击+3%</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[14002.0] = "{14002, \"转换精华\", 14002, 0, 2, 4, 999999, 1, 1, 0, {}, {}, {}, {{105,0},{53,0},{4,0}}, \"伟大召唤余留的精华，可用于将海贼新星、草帽联盟和强者的英雄<div fontcolor=#9e501b>随机转换</div>为同阵营的其他英雄\", 1, 0, 2, {}, 0, 0, 0, {1,20}, \"伟大召唤道具\", \"作用：英雄转换\", 1, 0}",
	[99080701.0] = "{99080701, \"7星镇灵耳环\", 8010001, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【7星镇灵耳环】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n暴击率+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>对辅助单位伤害+19%\", 1, 0, 2, {}, 0, 7, 0, {}, \"神装\", \"\", 0, 0}",
	[99140103.0] = "{99140103, \"1星玄护戒指\", 14010003, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【1星玄护戒指】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n抗控+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【玄护】：自己被附加控制效果时，回复自身生命值上限7%的生命值，1回合只可触发1次\", 1, 0, 2, {}, 0, 1, 0, {}, \"神装\", \"\", 0, 0}",
	[99110304.0] = "{99110304, \"3星龙威手镯\", 11010004, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【3星龙威手镯】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n暴击率+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【龙威】：攻击造成暴击时，有27%概率额外再造成目标生命上限8%的无视防御伤害（该伤害不超过攻击的1.2倍）\", 1, 0, 2, {}, 0, 3, 0, {}, \"神装\", \"\", 0, 0}",
	[50303.0] = "{50303, \"最强幸运星\", 50303, 0, 2, 5, 999999, 1, 1, 0, {}, {{effect_type=25,val=90902}}, {}, {}, \"幸运星中的佼佼者，幸运探宝活动中获得。用于激活称号<div fontcolor=#9e501b>「最强幸运星」\\n上阵气血+300，攻击+60，防御+45</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
