	[39071.0] = "{39071, \"新春宝箱\", 39070, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"金鼠带来专属你的诚挚祝福！开启可随机获得： \\n<div fontcolor=#9e501b>钻石*200</div> \\n<div fontcolor=#9e501b>精英召唤卷*2</div> \\n<div fontcolor=#9e501b>高级探宝券*1</div> \\n以上道具中的随机一件。\\n<div fontcolor=#ef3a3a>极低概率可获得5星随机碎片*50！</div>\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
