	[10456.0] = "{10456, \"恶魔战技\", 10456, 10, 4, 5, 1, 1, 1, 0, {}, {}, {}, {{113,1}}, \"恶魔战技，附带<div fontcolor=#9e501b>属性加成及2个随机高技能</div>，可供英雄穿戴后获得；可在锻造屋中<div fontcolor=#9e501b>合成</div>为更高级的觉醒战技\", 1, 0, 2, {}, 1, 0, 0, {}, \"英雄战技\", \"作用：技能获得\", 1, 0}",
