	[39505.0] = "{39505, \"4星极品套装自选礼盒\", 39027, 101, 2, 5, 999999, 1, 4, 0, {}, {}, {}, {}, \"神装套装自选礼盒，开启可自选获取下列4星极品的神装套装中的一套（含戒指、耳环、项链、手镯）： \\n<div fontcolor=#9e501b>狂怒套*1</div> \\n<div fontcolor=#9e501b>斗志套*1</div> \\n<div fontcolor=#9e501b>灵咏套*1</div>\", 1, 0, 2, {1}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[39026.0] = "{39026, \"圣光之心\", 39023, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"战国降临冒险大陆时带来的礼物，开启可获得： \\n<div fontcolor=#9e501b>钻石*200</div> \\n<div fontcolor=#9e501b>限定召唤卷*2</div> \\n<div fontcolor=#9e501b>高级探宝券*1</div> \\n<div fontcolor=#9e501b>5星随机碎片*50</div> \\n以上道具中的任意一件\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
