	[16010.0] = "{16010, \"降临符石\", 16010, 0, 2, 4, 999999, 1, 1, 0, {{10450,1600}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>降临:</div>复活后攻击提高10%，持续2回合\\n\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「降临」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[17003.0] = "{17003, \"强者意志\", 17003, 0, 2, 3, 999999, 1, 1, 0, {{1,10000}}, {}, {}, {{116,0}}, \"翡翠色的结晶，可用于<div fontcolor=#9e501b>升级信念</div>强者之怒\", 1, 0, 2, {}, 0, 0, 0, {1,34,37}, \"升级材料\", \"作用：圣物升级\", 1, 0}",
