	[80128.0] = "{80128, \"御田日记\", 80111, 500, 0, 3, 999999, 10, 0, 0, {}, {}, {}, {}, \"在光明乐章活动期间掉落的御田日记，御田日记带来光明和希望，可以在活动商城兑换奖励\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"\", 0, 0}",
	[39005.0] = "{39005, \"草帽联盟英雄碎片福袋\", 39005, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"装满草帽联盟英雄碎片的福袋，开启可以获得：\\n<div fontcolor=#9e501b>5星草帽联盟碎片*10</div>\\n<div fontcolor=#9e501b>5星草帽联盟碎片片*15</div>\\n<div fontcolor=#9e501b>5星草帽联盟碎片片*20</div>\\n<div fontcolor=#9e501b>5星草帽联盟碎片*30</div>\\n<div fontcolor=#9e501b>5星草帽联盟碎片*50</div>\\n以上道具中的任意一件。\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[50008.0] = "{50008, \"音舞绚蝶\", 50008, 0, 2, 4, 999999, 1, 1, 0, {}, {{effect_type=12,val=3000}}, {}, {}, \"音乐的力量鼓舞勇士前进的象征，可用于激活头像框<div fontcolor=#9e501b>「音舞绚蝶」</div>\", 1, 0, 2, {}, 1, 0, 1, {12}, \"头像框道具\", \"作用：头像框激活\", 0, 0}",
	[39036.0] = "{39036, \"松果宝盒\", 39035, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"小松鼠的最爱！会不会装满松果呢，开启可随机获得： \\n<div fontcolor=#9e501b>钻石*200</div> \\n<div fontcolor=#9e501b>限定召唤卷*2</div> \\n<div fontcolor=#9e501b>高级探宝券*1</div> \\n<div fontcolor=#9e501b>5星随机碎片*50</div> \\n以上道具中的任意一件。\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[80252.0] = "{80252, \"攻击力提升！\", 80252, 500, 0, 4, 999999, 10, 0, 0, {}, {}, {}, {}, \"奇境公会共享buff！ \\n<div fontcolor=#9e501b>所有英雄攻击+100，可叠加</div>\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"\", 0, 0}",
	[39067.0] = "{39067, \"幽灵之魂\", 39067, 101, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"可将其重生为以下任意幽灵：\\n<div fontcolor=#9e501b>收割幽灵*1\\n浪漫幽灵*1\\n破坏幽灵*1\\n疾风幽灵*1\\n诅咒幽灵*1</div>\", 1, 0, 2, {1}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[19004.0] = "{19004, \"闪闪果实碎片\", 19004, 38, 7, 4, 999999, 1, 1, 0, {}, {}, {}, {{142,1}}, \"可用于解锁图鉴<div fontcolor=#00ff00 outline=1,#000000>闪闪果实</div>，解锁后可<div fontcolor=#00ff00 outline=1,#000000>提升光系单位对暗系单位的攻击伤害</div>\", 1, 0, 2, {1}, 1, 0, 0, {1,52}, \"恶魔果实碎片\", \"解锁恶魔果实图鉴\", 0, 0}",
	[51001.0] = "{51001, \"超凡之巅\", 51001, 0, 2, 5, 1, 1, 1, 1, {}, {{effect_type=25,val=91101}}, {}, {}, \"称号<div fontcolor=#9e501b>「超凡之巅」</div>在“超凡段位赛”中达到排行榜第1名（到达王者段位）获得，持续一个赛季时间，\\n<div fontcolor=#9e501b>全体英雄生命+3%，攻击+3%</div>\", 1, 0, 2, {}, 1, 0, 0, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[99110802.0] = "{99110802, \"8星龙威项链\", 11010002, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【8星龙威项链】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n暴击率+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【龙威】：攻击造成暴击时，有32%概率额外再造成目标生命上限8%的无视防御伤害（该伤害不超过攻击的1.2倍）\", 1, 0, 2, {}, 0, 8, 0, {}, \"神装\", \"\", 0, 0}",
	[50035.0] = "{50035, \"万里阳光\", 50034, 0, 2, 4, 999999, 5, 1, 1, {}, {{effect_type=12,val={5100,1}}}, {}, {}, \"付费季度特权获得的专属头像框，可用于激活头像框<div fontcolor=#9e501b>「万里阳光」</div>\\n时效：月度30天，季度68天\", 1, 0, 2, {}, 354, 0, 1, {12}, \"头像框道具\", \"作用：头像框激活\", 0, 0}",
	[99060102.0] = "{99060102, \"1星破法项链\", 6010002, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【1星破法项链】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n攻击+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>对法师单位伤害+7%\", 1, 0, 2, {}, 0, 1, 0, {}, \"神装\", \"\", 0, 0}",
	[16103.0] = "{16103, \"灵巧符石\", 16103, 0, 2, 5, 999999, 1, 1, 0, {{10460,3}}, {}, {}, {{114,0},{124,0}}, \"<div fontcolor=#9e501b>灵巧:</div>无视所有减速效果；每回合开始，每存在1位同系友方英雄，自身速度依次提高3%/6%/9%/11%（无法与【迅捷】共存，优先生效）\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「灵巧」</div>觉醒霸气，英雄将在<div fontcolor=#9e501b>13星</div>开启觉醒\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：觉醒霸气学习\", 1, 0}",
	[99060502.0] = "{99060502, \"5星破法项链\", 6010002, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【5星破法项链】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n攻击+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>对法师单位伤害+15%\", 1, 0, 2, {}, 0, 5, 0, {}, \"神装\", \"\", 0, 0}",
	[99030701.0] = "{99030701, \"7星斗志耳环\", 3010001, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【7星斗志耳环】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n攻击+3%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>攻击+9%\", 1, 0, 2, {}, 0, 7, 0, {}, \"神装\", \"\", 0, 0}",
	[23049.0] = "{23049, \"玫瑰之恋(永久)\", 23049, 28, 2, 5, 999999, 1, 1, 0, {}, {{effect_type=34,val={117,0,{{3,5000}}}}}, {{117,0,3,5000}}, {}, \"白胡子专属<div fontcolor=#9e501b>稀有</div>皮肤，<div fontcolor=#9e501b>永久</div>有效，使用后可为白胡子穿戴，并解锁相应的形象和头像设置\", 1, 0, 2, {}, 1, 0, 0, {2}, \"皮肤道具\", \"作用：皮肤获取\", 0, 0}",
	[10424.0] = "{10424, \"战技·神之耀\", 10421, 0, 4, 4, 1, 5, 1, 0, {}, {{effect_type=30,val={10421,3}}}, {}, {{31,1},{2,0},{7,0}}, \"传说中象征主神荣耀的战技，可升星，根据不同星级附带不同数量的<div fontcolor=#9e501b>技能和属性加成</div>，可供英雄穿戴\", 1, 0, 2, {}, 1, 0, 0, {}, \"英雄战技\", \"作用：技能获得\", 1, 0}",
