	[16025.0] = "{16025, \"神佑符石\", 16025, 0, 2, 4, 999999, 1, 1, 0, {{10450,2200}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>神佑:</div>死亡时有8%概率复活，复活后恢复30%生命值\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「神佑」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
	[80124.0] = "{80124, \"御田日记\", 80111, 500, 0, 3, 999999, 10, 0, 0, {}, {}, {}, {}, \"在光明乐章活动期间掉落的御田日记，御田日记带来光明和希望，可以在活动商城兑换奖励\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"\", 0, 0}",
	[39003.0] = "{39003, \"自然英雄碎片福袋\", 39003, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"装满自然英雄碎片的福袋，开启可以获得：\\n<div fontcolor=#9e501b>5星自然碎片*10</div>\\n<div fontcolor=#9e501b>5星自然碎片片*15</div>\\n<div fontcolor=#9e501b>5星自然碎片片*20</div>\\n<div fontcolor=#9e501b>5星自然碎片*30</div>\\n<div fontcolor=#9e501b>5星自然碎片*50</div>\\n以上道具中的任意一件。\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[39034.0] = "{39034, \"粽夏之礼\", 39034, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"饱含粽香的端午豪礼，开启可随机获得： \\n<div fontcolor=#9e501b>高级召唤卷*2</div> \\n<div fontcolor=#9e501b>高级召唤卷*3</div> \\n<div fontcolor=#9e501b>高级召唤卷*5</div> \\n以上道具中的任意一件。\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[50037.0] = "{50037, \"兔丼霸主\", 50037, 0, 2, 4, 999999, 1, 1, 0, {}, {{effect_type=12,val=5300}}, {}, {}, \"参与兔丼监狱活动排行前三获得的头像框，可用于激活头像框<div fontcolor=#9e501b>「兔丼霸主」</div>\", 1, 0, 2, {}, 1, 0, 1, {12}, \"头像框道具\", \"作用：头像框激活\", 0, 0}",
	[99110803.0] = "{99110803, \"8星龙威戒指\", 11010003, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【8星龙威戒指】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n暴击率+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【龙威】：攻击造成暴击时，有32%概率额外再造成目标生命上限8%的无视防御伤害（该伤害不超过攻击的1.2倍）\", 1, 0, 2, {}, 0, 8, 0, {}, \"神装\", \"\", 0, 0}",
	[23052.0] = "{23052, \"岚月刃歌(永久)\", 23052, 28, 2, 5, 999999, 1, 1, 0, {}, {{effect_type=34,val={118,0,{{3,5000}}}}}, {{118,0,3,5000}}, {}, \"鹰眼专属<div fontcolor=#9e501b>稀有</div>皮肤，<div fontcolor=#9e501b>永久</div>有效，使用后可为鹰眼穿戴，并解锁相应的形象和头像设置\", 1, 0, 2, {}, 1, 0, 0, {2}, \"皮肤道具\", \"作用：皮肤获取\", 0, 0}",
	[89080901.0] = "{89080901, \"[极品]驱邪套装随机部位\", 8808, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机部位（耳环、项链、戒指、手镯）的[极品]9星镇灵神装\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n暴击率+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>对辅助单位伤害+15%\", 1, 0, 2, {}, 0, 5, 0, {}, \"神装\", \"\", 0, 0}",
