	[50002.0] = "{50002, \"竞技达人\", 50002, 0, 2, 4, 999999, 1, 1, 0, {}, {{effect_type=12,val=2100}}, {}, {{42,0}}, \"实力的象征，可用于激活头像框<div fontcolor=#9e501b>「竞技达人」</div>\", 1, 0, 2, {}, 1, 0, 1, {12}, \"头像框道具\", \"作用：头像框激活\", 0, 0}",
	[50902.0] = "{50902, \"心动闪烁\", 50902, 0, 2, 4, 999999, 1, 1, 0, {}, {{effect_type=25,val=99004}}, {}, {}, \"称号<div fontcolor=#9e501b>「心动闪烁」</div>:为答谢参与了闪烁北京线下活动的有爱之人，小助手特别定制的纪念称号\\n<div fontcolor=#9e501b>全体气血+10，攻击+10</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
