	[39530.0] = "{39530, \"海楼石随机礼包\", 39055, 100, 2, 5, 999999, 1, 4, 0, {}, {}, {}, {}, \"装满海楼石的礼包，开启后可随机获得以下数量海楼石： \\n<div fontcolor=#9e501b>海楼石*388</div>\\n<div fontcolor=#9e501b>海楼石*488</div>\\n<div fontcolor=#9e501b>海楼石*588</div>\\n<div fontcolor=#9e501b>海楼石*688</div>\\n<div fontcolor=#9e501b>海楼石*1688</div>\\n\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
