	[39017.0] = "{39017, \"春日暖阳礼包\", 80008, 100, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"暖春出游的纪念品，开启可获得： \\n<div fontcolor=#9e501b>钻石*388</div> \\n<div fontcolor=#9e501b>高级召唤卷*2</div> \\n<div fontcolor=#9e501b>高级探宝券*1</div> \\n<div fontcolor=#9e501b>强者招募令*1</div> \\n以上道具中的任意一件。\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[99955.0] = "{99955, \"每日签到礼包\", 34013, 100, 2, 5, 99999, 1, 4, 0, {}, {}, {}, {}, \"每日签到礼包，开启获得如下：\\n<div fontcolor=#9e501b>代金券*25W\\n突破卡*10000\\n贝里*5000W\\n英雄经验*5000W\\n高级寻宝卷*70\\n能力觉醒纹石*10\\n强化训练*50000\\n竞技挑战卷*10</div>\", 1, 0, 2, {}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[51226.0] = "{51226, \"贫道法号无名\", 51226, 0, 2, 5, 1, 1, 1, 0, {}, {{effect_type=25,val=91326}}, {}, {}, \"称号<div fontcolor=#9e501b>「贫道法号无名」</div>累计充值5000定制称号\\n<div fontcolor=#9e501b>气血+15%，攻击+15%，防御+15%，速度+15%</div>\", 1, 0, 2, {}, 1, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
	[39079.0] = "{39079, \"材料自选福袋\", 39012, 101, 2, 4, 999999, 1, 4, 0, {}, {}, {}, {}, \"极稀有的尊享材料自选礼包，开启可自选：\\n<div fontcolor=#9e501b>①强化训练*3000、技能符石自选包*1</div>\\n<div fontcolor=#9e501b>②神技精石*300、神技魂石*15</div>\\n<div fontcolor=#9e501b>③神技彤石*300000</div>\\n<div fontcolor=#9e501b>④突破卡*6000</div>\\n以上道具中的一件。\", 1, 0, 2, {2}, 1, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 1, 0}",
	[89120501.0] = "{89120501, \"[极品]神愈套装随机部位\", 8812, 100, 2, 5, 999999, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机部位（耳环、项链、戒指、手镯）的[极品]5星神愈神装\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n治疗+7%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【神愈】：治疗时，目标获得等同治疗量24%的护盾（该效果不可被驱散），持续2回合\", 1, 0, 2, {}, 0, 5, 0, {}, \"神装\", \"\", 0, 0}",
	[39141.0] = "{39141, \"极品4星极速自选神装\", 39113, 101, 2, 5, 999999, 1, 4, 0, {}, {}, {}, {}, \"威力无穷的4星极速神装，开启可自选获得以下其中1件神装：\\n<div fontcolor=#9e501b>4星极速耳环*1\\n4星极速项链*1\\n4星极速戒指*1\\n4星极速手镯*1</div>\", 1, 0, 2, {1}, 0, 0, 0, {2}, \"礼包\", \"作用：物品获取\", 0, 0}",
	[99080801.0] = "{99080801, \"8星镇灵耳环\", 8010001, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【8星镇灵耳环】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n暴击率+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>对辅助单位伤害+21%\", 1, 0, 2, {}, 0, 8, 0, {}, \"神装\", \"\", 0, 0}",
	[89060901.0] = "{89060901, \"[极品]抑法套装随机部位\", 8806, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机部位（耳环、项链、戒指、手镯）的[极品]9星破法神装\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n攻击+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>对法师单位伤害+15%\", 1, 0, 2, {}, 0, 5, 0, {}, \"神装\", \"\", 0, 0}",
	[99110404.0] = "{99110404, \"4星龙威手镯\", 11010004, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【4星龙威手镯】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n暴击率+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【龙威】：攻击造成暴击时，有28%概率额外再造成目标生命上限8%的无视防御伤害（该伤害不超过攻击的1.2倍）\", 1, 0, 2, {}, 0, 4, 0, {}, \"神装\", \"\", 0, 0}",
	[99050904.0] = "{99050904, \"9星穿甲手镯\", 5010004, 100, 2, 5, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【9星穿甲手镯】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n暴击率+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>对坦克单位伤害+23%\", 1, 0, 2, {}, 0, 9, 0, {}, \"神装\", \"\", 0, 0}",
	[80136.0] = "{80136, \"御田日记\", 80111, 500, 0, 3, 999999, 10, 0, 0, {}, {}, {}, {}, \"在御田日记活动期间掉落的御田日记，御田日记记载着传说的宝藏和空白的历史，可以在活动商城兑换奖励\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"\", 0, 0}",
	[99140203.0] = "{99140203, \"2星玄护戒指\", 14010003, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【1星玄护戒指】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n抗控+5%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>获得技能【玄护】：自己被附加控制效果时，回复自身生命值上限9%的生命值，1回合只可触发1次\", 1, 0, 2, {}, 0, 2, 0, {}, \"神装\", \"\", 0, 0}",
	[80260.0] = "{80260, \"弗拉格\", 80260, 500, 0, 4, 999999, 10, 0, 0, {}, {}, {}, {}, \"立下一个FLAG，<div fontcolor=#9e501b>如果下次行走步数与选择的步数相同</div>，则可以获得大量奖励\", 1, 0, 2, {}, 0, 0, 0, {}, \"活动道具\", \"\", 0, 0}",
