	[99030303.0] = "{99030303, \"3星斗志戒指\", 3010003, 100, 2, 4, 1, 5, 1, 0, {}, {}, {}, {}, \"可获得1个随机品阶（凡品、良品、极品）的【3星斗志戒指】\\n\\n<div fontcolor=#feeeba>集齐同星级</div><div fontcolor=#8bff8e>2件套</div><div fontcolor=#feeeba>可激活效果：</div>\\n攻击+3%<div fontcolor=#feeeba>\\n集齐同星级</div><div fontcolor=#8bff8e>4件套</div><div fontcolor=#feeeba>可激活效果：\\n</div>攻击+5%\", 1, 0, 2, {}, 0, 3, 0, {}, \"神装\", \"\", 0, 0}",
	[16009.0] = "{16009, \"回音符石\", 16009, 0, 2, 4, 999999, 1, 1, 0, {{10450,1600}}, {}, {}, {{114,0}}, \"<div fontcolor=#9e501b>回音:</div>复活后闪避率提高5%，持续2回合\\n\\n可使英雄<div fontcolor=#9e501b>领悟</div>或<div fontcolor=#9e501b>升级</div><div fontcolor=#9e501b>「回音」</div>技能，英雄将在<div fontcolor=#9e501b>6星</div>开启霸气领悟\", 1, 0, 2, {}, 0, 0, 0, {37,6,1}, \"技能道具\", \"作用：技能学习\", 1, 0}",
