	[59915.0] = "{59915, \"5级宝石自选箱\", 59915, 101, 2, 5, 99999999, 1, 4, 0, {}, {}, {}, {}, \"开启可自选任意属性的5级宝石\", 1, 0, 2, {1}, 1, 0, 0, {2}, \"宝石礼包\", \"作用:宝石获取\", 1, 0}",
