	[52129.0] = "{52129, \"佩罗斯\", 52129, 0, 2, 5, 99999999, 1, 1, 0, {}, {{effect_type=25,val=92129}}, {}, {}, \"超级称号<div fontcolor=#9e501b></div>:在星辰宝箱活动中获得，永久称号\\n<div fontcolor=#9e501b>生命+3%，攻击+3%</div>\", 1, 0, 2, {}, 0, 0, 1, {13}, \"称号道具\", \"作用：称号激活\", 0, 0}",
